INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C1','kor',1,2,'u7',1,'설명하는 글이 알려 주는 것 알기 — 설명하는 글은 무엇이 어떤 것인지·무엇을 어떻게 하는지 알려 준다는 것을 알고, 편지·일기 같은 다른 글과 가르며, 차례를 놓치지 않고 꼼꼼히 읽기',ARRAY['2국02-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C2','kor',1,2,'u7',3,'제목과 되풀이 낱말로 설명하는 것 찾기 — 제목을 실마리로 살피고 줄마다 되풀이 나오는 낱말을 찾아 이 글이 무엇에 대한 글인지 잡기, 한 번 나온 낱말이 왜 나왔는지 알기',ARRAY['2국02-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C3','kor',1,2,'u7',5,'문단을 합쳐 글 전체가 설명하는 것 찾기 — 제목에 설명하는 것이 나오지 않는 글에서 문단마다 무엇을 말하는지 보고 합쳐서 생각하기, 제목만 보고 답하지 않기, 한 문단에 나온 것을 전체로 여기지 않기',ARRAY['2국02-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C4','kor',1,2,'u7',3,'글을 읽고 새롭게 안 점 말하기 — 글에 적힌 내용으로만 새롭게 안 점을 말하고, 글에 없는 것을 지어내거나 내용을 뒤바꾸지 않기, 그것이 글 어디에 있는지 짚기',ARRAY['2국02-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C5','kor',1,2,'u7',7,'겪은 일을 네 칸으로 정리하기 — 이미 있었던 일을 언제·어디에서·무슨 일·그때 마음 네 칸으로 정리하고, 날마다 있는 평범한 일도 글감이 됨을 알기',ARRAY['2국03-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C6','kor',1,2,'u7',7,'마음을 여러 말로 나타내기 — 「좋았다·재미있었다」에서 그치지 않고 장면에 맞는 마음말을 까닭과 함께 쓰기, 마음말과 한 일을 나타내는 말을 가르기, 표정·장면과 어울리는 마음말 고르기',ARRAY['2국03-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C7','kor',1,2,'u7',10,'겪은 일이 잘 드러나는 글 쓰기 — 본 것·들은 것·한 일·느낀 것으로 재료를 모으고, 하고 싶은 말이 있는 글감을 골라, 많이 늘어놓기보다 한 가지를 장면이 그려지게 일이 일어난 차례로 쓰기, 나누어 읽을 때 좋은 점부터 찾기',ARRAY['2국03-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C8','kor',1,2,'u7',12,'겪은 일을 넣어 칭찬하는 글 쓰기 — 언제·칭찬하고 싶은 일·그때 마음 세 칸으로 쓰고, 견주거나 점수를 매기는 평가가 아니라 그 사람이 한 일을 칭찬하며, 친구뿐 아니라 가족·선생님·이웃에게도 쓰기',ARRAY['2국03-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X01','kor',1,'u7',ARRAY['K1-2-u7-C1']::text[],'설명하는 글과 편지·일기·이야기를 가르지 못하거나, 설명하는 글이 무엇을 알려 주는지 잡지 못한다','「읽고 나면 무엇을 어떻게 하는지 알게 되나?」 한 가지 물음으로 글 묶음을 둘로 나누어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X02','kor',1,'u7',ARRAY['K1-2-u7-C1','K1-2-u7-C2']::text[],'설명하는 글을 대충 읽어도 된다고 여기거나, 글의 길이·줄 수·글자 수처럼 내용과 상관없는 것부터 본다','만들기 설명을 한 줄 빼고 읽어 준 뒤 해 보게 하기 — 「어디서 막혔나요?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X03','kor',1,'u7',ARRAY['K1-2-u7-C2','K1-2-u7-C3']::text[],'제목에 나온 낱말을 그대로 설명하는 것이라고 여긴다(제목만 보고 답한다)','제목을 손으로 가리고 문단만 읽게 한 뒤 「무엇에 대한 글이었나?」 — 그다음 제목을 열어 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X04','kor',1,'u7',ARRAY['K1-2-u7-C2','K1-2-u7-C3']::text[],'한 줄·한 문단에만 나온 것(열매·두더지·구급차)을 글 전체가 설명하는 것으로 고른다','줄마다 손가락을 짚으며 「이 줄에도 나오나?」 세어 보기 — 모든 줄에 걸치는 것이 전체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X05','kor',1,'u7',ARRAY['K1-2-u7-C2']::text[],'되풀이 나오는 낱말을 찾지 못하거나, 찾는 방법(제목·되풀이 낱말)을 쓰지 않는다','줄마다 같은 낱말에 같은 색 동그라미 — 동그라미가 가장 많은 낱말이 실마리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X06','kor',1,'u7',ARRAY['K1-2-u7-C3','K1-2-u7-C4','K1-2-u7-C5']::text[],'글이나 겪은 일의 내용을 잘못 읽거나 뒤섞는다(문단과 내용을 엇갈려 잇기, 인물이 한 일 뒤바꾸기)','「그 내용이 몇째 줄에 있나요?」 줄을 짚게 하고 그 줄만 다시 소리 내어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X07','kor',1,'u7',ARRAY['K1-2-u7-C4']::text[],'글에 없는 것을 지어내어 새롭게 안 점이라고 말한다','「글 어디에 있었어?」 — 줄을 찾지 못하면 새롭게 안 점이 아니라 내 생각이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X08','kor',1,'u7',ARRAY['K1-2-u7-C5']::text[],'아직 하지 않은 일·하고 싶은 일을 겪은 일로 여긴다','「이미 있었던 일인가요?」 — 어제·오늘·지난번을 붙여 말이 되는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X09','kor',1,'u7',ARRAY['K1-2-u7-C5']::text[],'겪은 일은 생일·여행처럼 특별한 일이어야 한다고 여겨 날마다 있는 일을 글감에서 뺀다','오늘 아침부터 지금까지 마음이 움직였던 순간 세 가지를 찾아보기 — 그게 다 글감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X10','kor',1,'u7',ARRAY['K1-2-u7-C5','K1-2-u7-C8']::text[],'네 칸(언제·어디에서·무슨 일·그때 마음) 가운데 하나를 빠뜨리거나, 글자 수·친구와 견주기처럼 정리와 상관없는 것을 넣는다','네 칸 표에 손가락을 짚으며 「언제? 어디서? 무슨 일? 마음은?」 차례로 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X11','kor',1,'u7',ARRAY['K1-2-u7-C6','K1-2-u7-C7']::text[],'마음을 「좋았다·재미있었다·그냥」 한마디로 그치거나, 「아주아주」만 붙여 까닭 없이 늘인다','「왜 재미있었어?」 한 번 더 묻고, 그 대답을 마음말 앞에 붙여 다시 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X12','kor',1,'u7',ARRAY['K1-2-u7-C6','K1-2-u7-C5']::text[],'마음을 나타내는 말과 한 일을 나타내는 말(달려갔다·건져 냈다)을 가르지 못한다','「몸이 한 것이야, 마음이 느낀 것이야?」 두 칸 상자에 낱말 카드 나누어 넣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X13','kor',1,'u7',ARRAY['K1-2-u7-C6']::text[],'장면·표정과 마음말을 어긋나게 잇는다(웃는 얼굴에 「무섭다」, 겁날 때 「신났다」)','그 장면을 몸으로 흉내 내 보고 「지금 얼굴이 어때?」 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X14','kor',1,'u7',ARRAY['K1-2-u7-C7']::text[],'있었던 일을 많이 늘어놓을수록 잘 쓴 글이라고 여긴다','하루 일을 늘어놓은 글과 한 장면을 자세히 쓴 글을 나란히 읽고 「어느 쪽이 눈에 그려지나?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X15','kor',1,'u7',ARRAY['K1-2-u7-C7']::text[],'「갔다 왔다·별일 없었다·캤다」처럼 뭉뚱그려 써서 장면이 그려지지 않는다','「그때 무엇이 보였어? 무슨 소리가 났어? 손으로 뭘 했어?」 하나씩 물어 문장에 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X16','kor',1,'u7',ARRAY['K1-2-u7-C7']::text[],'글감을 고를 때 하고 싶은 말이 없는 일·남이 겪은 일을 고르거나, 겪은 일과 상관없는 재료를 늘어놓는다','「이 일을 누구에게 들려주고 싶어?」 — 들려줄 사람이 떠오르는 일이 글감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X17','kor',1,'u7',ARRAY['K1-2-u7-C7']::text[],'일이 일어난 차례를 뒤섞어 쓴다','일을 카드 한 장에 하나씩 적어 처음·가운데·끝 순서로 늘어놓은 뒤 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X18','kor',1,'u7',ARRAY['K1-2-u7-C7']::text[],'친구 글을 나누어 읽을 때 틀린 글자·글의 길이만 보고 좋은 점을 찾지 않는다','「좋은 표현 하나 찾기 → 마음이 드러난 곳 하나 찾기」 두 가지를 먼저 말한 뒤 고칠 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X19','kor',1,'u7',ARRAY['K1-2-u7-C8']::text[],'칭찬을 남과 견주거나 점수를 매기는 말로 쓰거나, 「착해·최고야」처럼 뭉뚱그리거나, 겉모습·가진 물건을 칭찬거리로 고른다','「그 사람이 한 일 중에 고마웠던 일은?」 — 한 일이 들어가야 다른 친구도 「맞아!」 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X20','kor',1,'u7',ARRAY['K1-2-u7-C8']::text[],'칭찬하는 글은 같은 반 친구에게만 쓸 수 있다고 여긴다','집·학교·동네에서 나를 도와준 사람을 한 명씩 떠올려 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#1','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',1,'mc','auto','이 쪽지는 무엇을 알려 주나요?',ARRAY['K1-2-u7-X01']::text[],true,'{"seq":1,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"이 쪽지는 무엇을 알려 주나요?","options":[{"t":"줄넘기 줄을 감는 방법","correct":true},{"t":"줄넘기를 가장 잘하는 친구","mis":"K1-2-u7-X01"},{"t":"줄넘기를 몇 번 넘었는지","mis":"K1-2-u7-X01"}],"explanation":["쪽지를 읽으면 줄을 어떻게 감는지 알게 돼요.","친구 이름이나 넘은 횟수는 나오지 않아요.","읽고 나서 무엇을 할 수 있게 되나요?"],"asset":{"type":"passage","lines":["줄을 반으로 접어 손잡이 둘을 모아 쥡니다.","줄을 손에 둥글게 감습니다.","줄 끝을 감은 줄 사이에 끼워 둡니다.","그러면 다음에 꺼낼 때 엉키지 않습니다."],"title":"「줄넘기 줄을 감는 방법」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이 쪽지는 무엇을 알려 주나요?","options":[{"t":"실내화를 빠는 방법","correct":true},{"t":"실내화를 산 가게","mis":"K1-2-u7-X01"},{"t":"실내화가 가장 예쁜 친구","mis":"K1-2-u7-X01"}],"explanation":["쪽지를 읽으면 실내화를 어떻게 빠는지 알게 돼요.","가게나 친구 이야기는 없어요.","읽고 나서 무엇을 할 수 있게 되나요?"],"asset":{"type":"passage","lines":["실내화를 물에 푹 적십니다.","솔에 비누를 묻혀 바닥과 앞코를 문지릅니다.","맑은 물로 비누 거품을 헹굽니다.","햇볕이 드는 곳에 세워 말립니다."],"title":"「실내화를 빠는 방법」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#2','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',1,'mc','auto','설명하는 글은 어느 것인가요?',ARRAY['K1-2-u7-X01']::text[],true,'{"seq":2,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"설명하는 글은 어느 것인가요?","options":[{"t":"「모래성을 단단하게 쌓는 방법」","correct":true},{"t":"「할머니께 보내는 편지」","mis":"K1-2-u7-X01"},{"t":"「어제 바닷가에 간 일」","mis":"K1-2-u7-X01"}],"explanation":["읽으면 무엇을 어떻게 하는지 알게 되는 글이에요.","편지와 겪은 일을 쓴 글은 설명하는 글이 아니에요.","「~하는 방법」을 알려 주나요?"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 설명하는 글은 어느 것인가요?","options":[{"t":"「손톱을 안전하게 깎는 방법」","correct":true},{"t":"「친구야, 생일 축하해」","mis":"K1-2-u7-X01"},{"t":"「내가 가장 좋아하는 날」","mis":"K1-2-u7-X01"}],"explanation":["읽으면 무엇을 어떻게 하는지 알게 되는 글이에요.","축하 편지와 내 이야기는 설명하는 글이 아니에요.","「~하는 방법」을 알려 주나요?"],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#3','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C2',1,'mc','auto','설명하는 글을 읽을 때 가장 먼저 살펴볼 것은 무엇인가요?',ARRAY['K1-2-u7-X02']::text[],false,'{"seq":3,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"설명하는 글을 읽을 때 가장 먼저 살펴볼 것은 무엇인가요?","options":[{"t":"무엇에 대해 알려 주는 글인지","correct":true},{"t":"글이 모두 몇 줄인지","mis":"K1-2-u7-X02"},{"t":"글씨가 얼마나 예쁜지","mis":"K1-2-u7-X02"}],"explanation":["무엇에 대한 글인지부터 잡아요.","줄 수나 글씨는 내용과 상관없어요.","「이 글은 무엇에 대한 글일까?」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#4','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C5',1,'mc','auto','내가 겪은 일은 어느 것인가요?',ARRAY['K1-2-u7-X08']::text[],true,'{"seq":4,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"내가 겪은 일은 어느 것인가요?","options":[{"t":"어제 운동장에서 넘어진 일","correct":true},{"t":"다음 주에 갈 소풍","mis":"K1-2-u7-X08"},{"t":"커서 되고 싶은 것","mis":"K1-2-u7-X08"}],"explanation":["이미 있었던 일이 겪은 일이에요.","소풍과 꿈은 아직 있지 않은 일이에요.","「어제·오늘·지난번」이 붙나요?"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 내가 겪은 일은 어느 것인가요?","options":[{"t":"오늘 아침 동생과 함께 학교에 온 일","correct":true},{"t":"방학에 가고 싶은 곳","mis":"K1-2-u7-X08"},{"t":"내일 먹을 간식","mis":"K1-2-u7-X08"}],"explanation":["이미 있었던 일이 겪은 일이에요.","가고 싶은 곳, 내일 간식은 아직 있지 않은 일이에요.","「어제·오늘·지난번」이 붙나요?"],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#5','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',2,'match','auto','우리 둘레의 설명하는 글과 그 글이 알려 주는 것을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u7-C1","difficulty":2,"kind":"match","stem":"우리 둘레의 설명하는 글과 그 글이 알려 주는 것을 선으로 이어 보세요.","pairs":[{"l":"우유갑에 적힌 글","r":"언제까지 마셔야 하는지"},{"l":"엘리베이터 안의 안내문","r":"몇 사람까지 탈 수 있는지"},{"l":"놀이터 입구의 안내판","r":"몇 살 어린이가 놀 수 있는지"}],"mis":"K1-2-u7-X01","explanation":["둘레에 설명하는 글이 많아요.","글마다 알려 주는 것이 달라요.","어디에 붙어 있는지 생각해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 우리 둘레의 설명하는 글과 그 글이 알려 주는 것을 선으로 이어 보세요.","pairs":[{"l":"과자 봉지 뒷면의 글","r":"무엇으로 만들었는지"},{"l":"세탁기 버튼 옆의 글","r":"어떻게 빨래를 돌리는지"},{"l":"지하철 노선도","r":"어느 역에서 갈아타는지"}],"explanation":["둘레에 설명하는 글이 많아요.","글마다 알려 주는 것이 달라요.","어디에 붙어 있는지 생각해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#6','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',2,'ox','auto','설명하는 글은 대충 읽어도 무엇을 해야 할지 다 알 수 있어요.',ARRAY['K1-2-u7-X02']::text[],false,'{"seq":6,"concept":"K1-2-u7-C1","difficulty":2,"kind":"ox","stem":"설명하는 글은 대충 읽어도 무엇을 해야 할지 다 알 수 있어요.","answer":"X","reason_options":[{"t":"차례나 방법을 놓치면 헤매게 되니까","correct":true},{"t":"제목만 읽어도 다 알 수 있으니까","mis":"K1-2-u7-X02"}],"mis":"K1-2-u7-X02","explanation":["꼼꼼히 읽어야 해요.","한 줄을 놓치면 처음부터 다시 할 수 있어요.","차례대로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#7','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C6',2,'mc','auto','겪은 일을 쓸 때 함께 쓰면 읽는 사람이 그 일을 더 잘 느낄 수 있는 것은 무엇인가요?',ARRAY['K1-2-u7-X10','K1-2-u7-X14']::text[],false,'{"seq":7,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"겪은 일을 쓸 때 함께 쓰면 읽는 사람이 그 일을 더 잘 느낄 수 있는 것은 무엇인가요?","options":[{"t":"그때 내 마음","correct":true},{"t":"친구가 받은 점수","mis":"K1-2-u7-X10"},{"t":"그날 먹은 반찬 이름 모두","mis":"K1-2-u7-X14"}],"explanation":["마음까지 쓰면 읽는 사람이 함께 느껴요.","친구 점수나 반찬 이름은 내 겪은 일과 멀어요.","그때 어떤 마음이었나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#8','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',2,'mc','auto','이 글을 읽고 실내화를 빨 때 맨 마지막에 할 일은 무엇인가요?',ARRAY['K1-2-u7-X06']::text[],true,'{"seq":8,"concept":"K1-2-u7-C1","difficulty":2,"kind":"mc","stem":"이 글을 읽고 실내화를 빨 때 맨 마지막에 할 일은 무엇인가요?","options":[{"t":"햇볕이 드는 곳에 세워 말려요","correct":true},{"t":"솔에 비누를 묻혀 문질러요","mis":"K1-2-u7-X06"},{"t":"실내화를 물에 푹 적셔요","mis":"K1-2-u7-X06"}],"explanation":["넷째 줄이 마지막이에요.","문지르기와 적시기는 앞에서 해요.","줄 차례를 짚어요."],"asset":{"type":"passage","lines":["실내화를 물에 푹 적십니다.","솔에 비누를 묻혀 바닥과 앞코를 문지릅니다.","맑은 물로 비누 거품을 헹굽니다.","햇볕이 드는 곳에 세워 말립니다."],"title":"「실내화를 빠는 방법」"},"variant_rule":{"alt":[{"stem":"이 글을 읽고 우유갑을 정리할 때 맨 처음 할 일은 무엇인가요?","options":[{"t":"물을 조금 넣어 헹궈요","correct":true},{"t":"손바닥으로 눌러 납작하게 만들어요","mis":"K1-2-u7-X06"},{"t":"모으는 상자에 넣어요","mis":"K1-2-u7-X06"}],"explanation":["첫째 줄이 처음이에요.","누르기와 넣기는 뒤에서 해요.","줄 차례를 짚어요."],"asset":{"type":"passage","lines":["다 마신 우유갑에 물을 조금 넣어 헹굽니다.","우유갑의 입구를 활짝 펼칩니다.","손바닥으로 눌러 납작하게 만듭니다.","우유갑을 모으는 상자에 넣습니다."],"title":"「다 마신 우유갑을 정리하는 방법」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#9','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C5',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#10','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',3,'error','auto','설명하는 글을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#1','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C1',2,'mc','auto','이 글을 읽으면 무엇을 할 수 있게 되나요?',ARRAY['K1-2-u7-X01']::text[],true,'{"seq":1,"concept":"K1-2-u7-C1","difficulty":2,"kind":"mc","stem":"이 글을 읽으면 무엇을 할 수 있게 되나요?","options":[{"t":"다 마신 우유갑을 정리할 수 있어요","correct":true},{"t":"우유를 맛있게 만들 수 있어요","mis":"K1-2-u7-X01"},{"t":"우유갑 그림을 그릴 수 있어요","mis":"K1-2-u7-X01"}],"explanation":["헹구고 펼치고 눌러 모으는 방법이에요.","우유 만들기, 그림 그리기는 나오지 않아요.","읽고 나서 할 수 있게 되는 일."],"asset":{"type":"passage","lines":["다 마신 우유갑에 물을 조금 넣어 헹굽니다.","우유갑의 입구를 활짝 펼칩니다.","손바닥으로 눌러 납작하게 만듭니다.","우유갑을 모으는 상자에 넣습니다."],"title":"「다 마신 우유갑을 정리하는 방법」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이 글을 읽으면 무엇을 할 수 있게 되나요?","options":[{"t":"물감을 쓴 붓을 씻을 수 있어요","correct":true},{"t":"물감을 새로 살 수 있어요","mis":"K1-2-u7-X01"},{"t":"붓으로 그림을 잘 그릴 수 있어요","mis":"K1-2-u7-X01"}],"explanation":["흔들고 닦고 모아 말리는 방법이에요.","물감 사기, 그림 잘 그리기는 나오지 않아요.","읽고 나서 할 수 있게 되는 일."],"asset":{"type":"passage","lines":["물감을 다 쓰면 붓을 물통에 넣어 살살 흔듭니다.","붓을 휴지에 대고 물기를 닦습니다.","붓 끝을 손가락으로 모아 가지런히 합니다.","붓을 눕혀서 말립니다."],"title":"「붓을 씻는 방법」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#2','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C5',2,'match','auto','겪은 일을 정리하는 칸과 알맞은 내용을 선으로 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"K1-2-u7-C5","difficulty":2,"kind":"match","stem":"겪은 일을 정리하는 칸과 알맞은 내용을 선으로 이어 보세요.","pairs":[{"l":"언제","r":"어제 저녁에"},{"l":"어디에서","r":"놀이터에서"},{"l":"무슨 일","r":"그네를 타다 신발이 날아갔어요"}],"mis":"K1-2-u7-X10","explanation":["칸마다 들어갈 것이 달라요.","때 · 곳 · 있었던 일.","칸 이름을 물음으로 바꿔 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#3','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C1',3,'mc','auto','설명하는 글을 대충 읽고 만들기를 하면 어떻게 될 수 있나요?',ARRAY['K1-2-u7-X02']::text[],false,'{"seq":3,"concept":"K1-2-u7-C1","difficulty":3,"kind":"mc","stem":"설명하는 글을 대충 읽고 만들기를 하면 어떻게 될 수 있나요?","options":[{"t":"차례를 놓쳐 처음부터 다시 해야 할 수 있어요","correct":true},{"t":"더 빨리 멋지게 끝나요","mis":"K1-2-u7-X02"},{"t":"아무 상관이 없어요","mis":"K1-2-u7-X02"}],"explanation":["한 줄을 놓치면 막혀요.","빨리 끝나는 것이 아니라 헤매게 돼요.","꼼꼼히, 차례대로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#4','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C5',3,'error','auto','겪은 일을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#5','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C6',3,'ox','auto','겪은 일을 쓸 때 「재미있었다」 한마디면 마음이 충분히 드러나요.',ARRAY['K1-2-u7-X11']::text[],true,'{"seq":5,"concept":"K1-2-u7-C6","difficulty":3,"kind":"ox","stem":"겪은 일을 쓸 때 「재미있었다」 한마디면 마음이 충분히 드러나요.","answer":"X","reason_options":[{"t":"왜 그런 마음이었는지까지 써야 잘 전해지니까","correct":true},{"t":"마음은 짧을수록 좋으니까","mis":"K1-2-u7-X11"}],"mis":"K1-2-u7-X11","explanation":["까닭을 넣어요.","「재미있었다」만으로는 어떤 재미인지 몰라요.","「왜?」를 붙여 봐요."],"variant_rule":{"alt":[{"stem":"겪은 일을 쓸 때 마음을 나타내는 말은 「좋았다」 하나만 있어요.","answer":"X","reason_options":[{"t":"설렜다·뿌듯했다·서운했다처럼 마음말은 아주 많으니까","correct":true},{"t":"다른 말은 어려워서 쓰면 안 되니까","mis":"K1-2-u7-X11"}],"explanation":["마음말은 많아요.","장면에 맞는 말을 골라요.","여러 마음말을 모아 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#6','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C1',3,'mc','auto','설명하는 글인지 알아보는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X02','K1-2-u7-X01']::text[],false,'{"seq":6,"concept":"K1-2-u7-C1","difficulty":3,"kind":"mc","stem":"설명하는 글인지 알아보는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽고 나면 무엇을 어떻게 하는지 알게 되는지 살펴요","correct":true},{"t":"글이 길면 설명하는 글이에요","mis":"K1-2-u7-X02"},{"t":"「나」라는 말이 나오면 설명하는 글이에요","mis":"K1-2-u7-X01"}],"explanation":["알게 되는 것이 있는지가 기준이에요.","길이나 「나」는 기준이 아니에요.","읽고 나서 무엇을 알게 되나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#7','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C1',3,'mc','auto','설명하는 글로 쓰기에 가장 알맞은 제목은 어느 것인가요?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":7,"concept":"K1-2-u7-C1","difficulty":3,"kind":"mc","stem":"설명하는 글로 쓰기에 가장 알맞은 제목은 어느 것인가요?","options":[{"t":"「종이컵으로 전화기를 만드는 방법」","correct":true},{"t":"「내가 가장 행복했던 날」","mis":"K1-2-u7-X01"},{"t":"「짝에게 하고 싶은 말」","mis":"K1-2-u7-X01"}],"explanation":["만드는 방법을 알려 주는 글이에요.","행복했던 날은 겪은 일, 하고 싶은 말은 편지에 가까워요.","무엇을 어떻게 하나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#8','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C2',4,'sa','auto','제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇에 대해 알려 주는지 낱말로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u7-C2","difficulty":4,"kind":"sa","stem":"제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇에 대해 알려 주는지 낱말로 쓰세요.","answer":["붓","붓을 씻는 방법","붓 씻는 방법","붓 씻기","붓을 씻는 법"],"explanation":["네 줄에 모두 「붓」이 나와요.","이 글은 붓을 씻는 방법을 알려 줘요.","되풀이 낱말이 실마리."],"asset":{"type":"passage","lines":["물감을 다 쓰면 붓을 물통에 넣어 살살 흔듭니다.","붓을 휴지에 대고 물기를 닦습니다.","붓 끝을 손가락으로 모아 가지런히 합니다.","붓을 눕혀서 말립니다."],"title":"제목을 가린 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#9','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C1',4,'essay','teacher','설명하는 글을 보고 무언가를 해 본 일을 쓰세요. 무엇을 읽었는지와 그다음 무엇을 했는지를 차례로 두 문장 넘게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C1","difficulty":4,"kind":"essay","stem":"설명하는 글을 보고 무언가를 해 본 일을 쓰세요. 무엇을 읽었는지와 그다음 무엇을 했는지를 차례로 두 문장 넘게 쓰세요.","answer_guide":{"answer":"예: 엄마와 라면 봉지 뒤에 적힌 끓이는 방법을 읽었어요. 물을 먼저 끓이고 면과 스프를 넣어 함께 끓였어요. — 읽은 글과 한 일이 차례로 있으면 맞아요.","scoring_points":["무엇을 읽었는지 있는가","읽은 뒤 한 일이 있는가","차례대로 썼는가"]},"explanation":["읽은 것 → 한 것.","안내판·봉지 글·만들기 설명 무엇이든 좋아요.","차례를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#10','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C6',4,'essay','teacher','어제나 오늘 있었던 일 하나를 골라, 그때 내 마음까지 넣어 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C6","difficulty":4,"kind":"essay","stem":"어제나 오늘 있었던 일 하나를 골라, 그때 내 마음까지 넣어 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 오늘 아침 동생이 내 가방을 들어 주었어요. 무거웠던 어깨가 가벼워져서 고마웠어요. — 이미 있었던 일과 까닭 있는 마음이 있으면 맞아요.","scoring_points":["이미 있었던 일인가","그때 마음이 있는가","마음에 까닭이 있는가"]},"explanation":["있었던 일 + 마음.","「재미있었다」만 쓰지 않아요.","왜 그런 마음이었나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#1','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C2',1,'mc','auto','이 글은 무엇을 설명하나요?',ARRAY['K1-2-u7-X04']::text[],true,'{"seq":1,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"이 글은 무엇을 설명하나요?","options":[{"t":"해바라기","correct":true},{"t":"새","mis":"K1-2-u7-X04"},{"t":"기름","mis":"K1-2-u7-X04"}],"explanation":["처음부터 끝까지 해바라기 이야기예요.","새와 기름은 마지막 줄에만 나와요.","모든 줄에 나오는 것."],"asset":{"type":"passage","lines":["해바라기는 키가 큰 여름꽃입니다.","해바라기는 노랗고 커다란 꽃을 피웁니다.","해바라기 꽃 가운데에는 씨앗이 촘촘히 모여 있습니다.","해바라기 씨앗은 새들의 먹이가 되고, 사람들은 그 씨앗으로 기름을 짭니다."],"title":"「해바라기」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이 글은 무엇을 설명하나요?","options":[{"t":"거북","correct":true},{"t":"모래","mis":"K1-2-u7-X04"},{"t":"알","mis":"K1-2-u7-X04"}],"explanation":["처음부터 끝까지 거북 이야기예요.","모래와 알은 셋째 줄에만 나와요.","모든 줄에 나오는 것."],"asset":{"type":"passage","lines":["거북은 단단한 등딱지를 가진 동물입니다.","거북은 위험하면 머리와 다리를 등딱지 속에 넣습니다.","바다거북은 바닷가 모래에 구멍을 파고 알을 낳습니다.","거북은 아주 오래 사는 동물입니다."],"title":"「거북」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#2','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C2',1,'mc','auto','글에서 줄마다 되풀이해 나오는 낱말은 어느 것인가요?',ARRAY['K1-2-u7-X05']::text[],true,'{"seq":2,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"글에서 줄마다 되풀이해 나오는 낱말은 어느 것인가요?","options":[{"t":"해바라기","correct":true},{"t":"씨앗","mis":"K1-2-u7-X05"},{"t":"기름","mis":"K1-2-u7-X05"}],"explanation":["네 줄에 모두 「해바라기」가 있어요.","씨앗은 두 줄, 기름은 한 줄이에요.","줄마다 동그라미를 쳐 봐요."],"asset":{"type":"passage","lines":["해바라기는 키가 큰 여름꽃입니다.","해바라기는 노랗고 커다란 꽃을 피웁니다.","해바라기 꽃 가운데에는 씨앗이 촘촘히 모여 있습니다.","해바라기 씨앗은 새들의 먹이가 되고, 사람들은 그 씨앗으로 기름을 짭니다."],"title":"「해바라기」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글에서 줄마다 되풀이해 나오는 낱말은 어느 것인가요?","options":[{"t":"돋보기","correct":true},{"t":"개미","mis":"K1-2-u7-X05"},{"t":"글씨","mis":"K1-2-u7-X05"}],"explanation":["네 줄에 모두 「돋보기」가 있어요.","개미와 글씨는 한 줄씩이에요.","줄마다 동그라미를 쳐 봐요."],"asset":{"type":"passage","lines":["돋보기는 작은 것을 크게 보여 주는 도구입니다.","돋보기로 보면 개미 다리에 난 털도 보입니다.","할머니는 돋보기를 쓰고 작은 글씨를 읽으십니다.","과학 시간에는 돋보기로 나뭇잎의 잎맥을 관찰합니다."],"title":"「돋보기」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#3','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C2',1,'mc','auto','설명하는 것을 찾을 때 함께 살펴볼 두 가지는 무엇인가요?',ARRAY['K1-2-u7-X02']::text[],false,'{"seq":3,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"설명하는 것을 찾을 때 함께 살펴볼 두 가지는 무엇인가요?","options":[{"t":"제목과 되풀이 나오는 낱말","correct":true},{"t":"글의 줄 수와 글자 수","mis":"K1-2-u7-X02"},{"t":"그림 색깔과 글씨 크기","mis":"K1-2-u7-X02"}],"explanation":["제목과 되풀이 낱말이 실마리예요.","줄 수, 색깔은 실마리가 아니에요.","두 가지를 함께."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#4','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C4',1,'mc','auto','글을 읽고 새롭게 안 점을 바르게 말한 것은 어느 것인가요?',ARRAY['K1-2-u7-X07']::text[],true,'{"seq":4,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 새롭게 안 점을 바르게 말한 것은 어느 것인가요?","options":[{"t":"거북은 위험하면 머리와 다리를 등딱지 속에 넣는다는 것을 알았어요.","correct":true},{"t":"거북은 하늘을 날 수 있다는 것을 알았어요.","mis":"K1-2-u7-X07"},{"t":"거북은 빨리 달리기를 잘한다는 것을 알았어요.","mis":"K1-2-u7-X07"}],"explanation":["둘째 줄에 적혀 있어요.","하늘을 날거나 빨리 달린다는 말은 없어요.","글 어디에 있나요?"],"asset":{"type":"passage","lines":["거북은 단단한 등딱지를 가진 동물입니다.","거북은 위험하면 머리와 다리를 등딱지 속에 넣습니다.","바다거북은 바닷가 모래에 구멍을 파고 알을 낳습니다.","거북은 아주 오래 사는 동물입니다."],"title":"「거북」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 새롭게 안 점을 바르게 말한 것은 어느 것인가요?","options":[{"t":"돋보기로 나뭇잎의 잎맥을 관찰할 수 있다는 것을 알았어요.","correct":true},{"t":"돋보기로 멀리 있는 별을 본다는 것을 알았어요.","mis":"K1-2-u7-X07"},{"t":"돋보기는 물에 넣어 쓴다는 것을 알았어요.","mis":"K1-2-u7-X07"}],"explanation":["넷째 줄에 적혀 있어요.","별이나 물 이야기는 없어요.","글 어디에 있나요?"],"asset":{"type":"passage","lines":["돋보기는 작은 것을 크게 보여 주는 도구입니다.","돋보기로 보면 개미 다리에 난 털도 보입니다.","할머니는 돋보기를 쓰고 작은 글씨를 읽으십니다.","과학 시간에는 돋보기로 나뭇잎의 잎맥을 관찰합니다."],"title":"「돋보기」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#5','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C3',2,'match','auto','글의 줄과 그 줄이 알려 주는 것을 선으로 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u7-C3","difficulty":2,"kind":"match","stem":"글의 줄과 그 줄이 알려 주는 것을 선으로 이어 보세요.","pairs":[{"l":"첫째 줄","r":"어떤 동물인지"},{"l":"둘째 줄","r":"위험할 때 하는 일"},{"l":"셋째 줄","r":"알을 낳는 곳"}],"mis":"K1-2-u7-X06","explanation":["줄마다 알려 주는 것이 달라요.","어떤 것 · 하는 일 · 사는 모습.","줄을 짚으며 읽어요."],"asset":{"type":"passage","lines":["거북은 단단한 등딱지를 가진 동물입니다.","거북은 위험하면 머리와 다리를 등딱지 속에 넣습니다.","바다거북은 바닷가 모래에 구멍을 파고 알을 낳습니다.","거북은 아주 오래 사는 동물입니다."],"title":"「거북」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#6','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C2',2,'mc','auto','제목만 보고도 무엇을 설명하는지 알 수 있는 것은 어느 것인가요?',ARRAY['K1-2-u7-X03']::text[],true,'{"seq":6,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"제목만 보고도 무엇을 설명하는지 알 수 있는 것은 어느 것인가요?","options":[{"t":"「소금」","correct":true},{"t":"「하얗고 짠 친구」","mis":"K1-2-u7-X03"},{"t":"「바다에서 온 선물」","mis":"K1-2-u7-X03"}],"explanation":["제목에 설명하는 것이 그대로 있어요.","다른 둘은 글을 읽어야 알 수 있어요.","제목 안에 그 낱말이 있나요?"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 제목만 보고도 무엇을 설명하는지 알 수 있는 것은 어느 것인가요?","options":[{"t":"「돋보기」","correct":true},{"t":"「작은 것이 커져요」","mis":"K1-2-u7-X03"},{"t":"「신기한 유리」","mis":"K1-2-u7-X03"}],"explanation":["제목에 설명하는 것이 그대로 있어요.","다른 둘은 글을 읽어야 알 수 있어요.","제목 안에 그 낱말이 있나요?"],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#7','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C4',2,'ox','auto','「돋보기는 멀리 있는 별을 보는 도구예요.」는 이 글에서 새롭게 안 점이에요.',ARRAY['K1-2-u7-X07']::text[],false,'{"seq":7,"concept":"K1-2-u7-C4","difficulty":2,"kind":"ox","stem":"「돋보기는 멀리 있는 별을 보는 도구예요.」는 이 글에서 새롭게 안 점이에요.","answer":"X","reason_options":[{"t":"글에는 작은 것을 크게 보여 준다고 적혀 있으니까","correct":true},{"t":"「도구」라는 말이 글에 있으니까","mis":"K1-2-u7-X07"}],"mis":"K1-2-u7-X07","explanation":["글에 없는 내용이에요.","낱말 하나가 같다고 새롭게 안 점이 되지 않아요.","그 줄을 찾아봐요."],"asset":{"type":"passage","lines":["돋보기는 작은 것을 크게 보여 주는 도구입니다.","돋보기로 보면 개미 다리에 난 털도 보입니다.","할머니는 돋보기를 쓰고 작은 글씨를 읽으십니다.","과학 시간에는 돋보기로 나뭇잎의 잎맥을 관찰합니다."],"title":"「돋보기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#8','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C2',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#9','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C4',2,'mc','auto','새롭게 안 점을 말하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X07']::text[],false,'{"seq":9,"concept":"K1-2-u7-C4","difficulty":2,"kind":"mc","stem":"새롭게 안 점을 말하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"글에서 읽은 내용으로 말해요","correct":true},{"t":"그럴 것 같은 것을 지어내어 말해요","mis":"K1-2-u7-X07"},{"t":"글과 상관없이 내가 좋아하는 것을 말해요","mis":"K1-2-u7-X07"}],"explanation":["새롭게 안 점은 글에 있어요.","지어내거나 상관없는 것은 아니에요.","「글 어디에 있었지?」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#10','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C2',3,'error','auto','「거북」이 무엇을 설명하는지 찾은 방법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#1','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C2',2,'mc','auto','이 글에서 줄마다 되풀이 나오는 낱말은 어느 것인가요?',ARRAY['K1-2-u7-X05']::text[],true,'{"seq":1,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"이 글에서 줄마다 되풀이 나오는 낱말은 어느 것인가요?","options":[{"t":"소금","correct":true},{"t":"바닷물","mis":"K1-2-u7-X05"},{"t":"음식","mis":"K1-2-u7-X05"}],"explanation":["네 줄 모두 「소금」이 있어요.","바닷물·음식은 한 줄씩이에요.","되풀이 낱말이 실마리."],"asset":{"type":"passage","lines":["소금은 짠맛이 나는 하얀 알갱이입니다.","소금은 바닷물을 햇볕에 말려서 얻습니다.","음식에 소금을 조금 넣으면 맛이 살아납니다.","배추를 소금에 절이면 오래 두고 먹을 수 있습니다."],"title":"「소금」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이 글에서 줄마다 되풀이 나오는 낱말은 어느 것인가요?","options":[{"t":"거북","correct":true},{"t":"등딱지","mis":"K1-2-u7-X05"},{"t":"모래","mis":"K1-2-u7-X05"}],"explanation":["네 줄에 거북이 나와요(바다거북 포함).","등딱지는 두 줄, 모래는 한 줄이에요.","되풀이 낱말이 실마리."],"asset":{"type":"passage","lines":["거북은 단단한 등딱지를 가진 동물입니다.","거북은 위험하면 머리와 다리를 등딱지 속에 넣습니다.","바다거북은 바닷가 모래에 구멍을 파고 알을 낳습니다.","거북은 아주 오래 사는 동물입니다."],"title":"「거북」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#2','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C3',2,'match','auto','글의 줄과 그 줄이 알려 주는 것을 선으로 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"K1-2-u7-C3","difficulty":2,"kind":"match","stem":"글의 줄과 그 줄이 알려 주는 것을 선으로 이어 보세요.","pairs":[{"l":"첫째 줄","r":"어떤 꽃인지"},{"l":"셋째 줄","r":"씨앗이 있는 곳"},{"l":"넷째 줄","r":"씨앗이 주는 도움"}],"mis":"K1-2-u7-X06","explanation":["줄마다 알려 주는 것이 달라요.","어떤 것 · 있는 곳 · 주는 도움.","줄을 짚으며 읽어요."],"asset":{"type":"passage","lines":["해바라기는 키가 큰 여름꽃입니다.","해바라기는 노랗고 커다란 꽃을 피웁니다.","해바라기 꽃 가운데에는 씨앗이 촘촘히 모여 있습니다.","해바라기 씨앗은 새들의 먹이가 되고, 사람들은 그 씨앗으로 기름을 짭니다."],"title":"「해바라기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#3','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C2',3,'mc','auto','이 글에 「배추」가 나온 까닭은 무엇인가요?',ARRAY['K1-2-u7-X04','K1-2-u7-X03']::text[],true,'{"seq":3,"concept":"K1-2-u7-C2","difficulty":3,"kind":"mc","stem":"이 글에 「배추」가 나온 까닭은 무엇인가요?","options":[{"t":"소금이 하는 일을 보여 주려고","correct":true},{"t":"배추를 설명하려고","mis":"K1-2-u7-X04"},{"t":"배추가 제목이라서","mis":"K1-2-u7-X03"}],"explanation":["소금에 절이면 오래 둔다는 것을 알려 줘요.","배추는 한 줄뿐이고 제목도 아니에요.","글 전체는 소금 이야기."],"asset":{"type":"passage","lines":["소금은 짠맛이 나는 하얀 알갱이입니다.","소금은 바닷물을 햇볕에 말려서 얻습니다.","음식에 소금을 조금 넣으면 맛이 살아납니다.","배추를 소금에 절이면 오래 두고 먹을 수 있습니다."],"title":"「소금」"},"variant_rule":{"alt":[{"stem":"이 글에 「할머니」가 나온 까닭은 무엇인가요?","options":[{"t":"돋보기를 쓰는 때를 보여 주려고","correct":true},{"t":"할머니를 설명하려고","mis":"K1-2-u7-X04"},{"t":"할머니가 제목이라서","mis":"K1-2-u7-X03"}],"explanation":["작은 글씨를 읽을 때 쓴다는 것을 알려 줘요.","할머니는 한 줄뿐이고 제목도 아니에요.","글 전체는 돋보기 이야기."],"asset":{"type":"passage","lines":["돋보기는 작은 것을 크게 보여 주는 도구입니다.","돋보기로 보면 개미 다리에 난 털도 보입니다.","할머니는 돋보기를 쓰고 작은 글씨를 읽으십니다.","과학 시간에는 돋보기로 나뭇잎의 잎맥을 관찰합니다."],"title":"「돋보기」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#4','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C4',3,'error','auto','「거북」을 읽고 새롭게 안 점을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#5','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C2',3,'ox','auto','제목에 나온 낱말이 언제나 그 글이 설명하는 것이에요.',ARRAY['K1-2-u7-X03']::text[],false,'{"seq":5,"concept":"K1-2-u7-C2","difficulty":3,"kind":"ox","stem":"제목에 나온 낱말이 언제나 그 글이 설명하는 것이에요.","answer":"X","reason_options":[{"t":"제목은 실마리일 뿐이라 글도 함께 읽어야 하니까","correct":true},{"t":"제목은 글쓴이가 답을 적어 두는 곳이니까","mis":"K1-2-u7-X03"}],"mis":"K1-2-u7-X03","explanation":["제목만으로 알 수 없는 글도 있어요.","「작아도 힘센 일꾼」처럼요.","제목 + 되풀이 낱말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#6','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C4',3,'mc','auto','「돋보기」를 읽은 소미가 「돋보기는 할머니만 쓰는 물건이구나.」 했어요. 소미에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X06','K1-2-u7-X07']::text[],false,'{"seq":6,"concept":"K1-2-u7-C4","difficulty":3,"kind":"mc","stem":"「돋보기」를 읽은 소미가 「돋보기는 할머니만 쓰는 물건이구나.」 했어요. 소미에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"넷째 줄을 봐, 과학 시간에 관찰할 때도 써.","correct":true},{"t":"맞아, 할머니만 쓰는 물건이야.","mis":"K1-2-u7-X06"},{"t":"아니야, 돋보기는 아기만 써.","mis":"K1-2-u7-X07"}],"explanation":["글에 다른 쓰임도 있어요.","한 줄만 보고 말하면 글과 달라져요.","줄을 다 읽어요."],"asset":{"type":"passage","lines":["돋보기는 작은 것을 크게 보여 주는 도구입니다.","돋보기로 보면 개미 다리에 난 털도 보입니다.","할머니는 돋보기를 쓰고 작은 글씨를 읽으십니다.","과학 시간에는 돋보기로 나뭇잎의 잎맥을 관찰합니다."],"title":"「돋보기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#7','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C3',3,'mc','auto','이 글 전체가 알려 주는 것은 무엇인가요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":7,"concept":"K1-2-u7-C3","difficulty":3,"kind":"mc","stem":"이 글 전체가 알려 주는 것은 무엇인가요?","options":[{"t":"거북이 어떤 동물이고 어떻게 사는지","correct":true},{"t":"바닷가 모래가 어떤지","mis":"K1-2-u7-X04"},{"t":"거북 알을 지키는 방법","mis":"K1-2-u7-X04"}],"explanation":["네 줄을 합치면 거북 이야기예요.","모래와 알은 한 줄에만 나와요.","모든 줄을 합쳐요."],"asset":{"type":"passage","lines":["거북은 단단한 등딱지를 가진 동물입니다.","거북은 위험하면 머리와 다리를 등딱지 속에 넣습니다.","바다거북은 바닷가 모래에 구멍을 파고 알을 낳습니다.","거북은 아주 오래 사는 동물입니다."],"title":"「거북」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#8','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C2',4,'sa','auto','제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇을 설명하는지 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u7-C2","difficulty":4,"kind":"sa","stem":"제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇을 설명하는지 쓰세요.","answer":["고드름"],"explanation":["네 줄 모두 「고드름」이 나와요.","이 글은 고드름을 설명해요.","되풀이 낱말이 실마리."],"asset":{"type":"passage","lines":["겨울 아침 처마 끝에 고드름이 매달립니다.","고드름은 녹은 눈이 떨어지다 다시 얼어서 생깁니다.","고드름은 해가 나면 똑똑 녹아 떨어집니다.","고드름 밑으로 지나갈 때는 조심해야 합니다."],"title":"제목을 가린 글"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇을 설명하는지 쓰세요.","answer":["연필깎이","연필 깎이"],"explanation":["세 줄 모두 「연필깎이」가 나와요.","이 글은 연필깎이를 설명해요.","되풀이 낱말이 실마리."],"asset":{"type":"passage","lines":["연필이 뭉툭해지면 연필깎이에 넣고 손잡이를 돌립니다.","연필깎이 안의 칼날이 연필 끝을 뾰족하게 깎습니다.","연필깎이에 부스러기가 차면 서랍을 빼서 비웁니다."],"title":"제목을 가린 글"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#9','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C4',4,'essay','teacher','「소금」을 읽고 새롭게 안 점을 「나는 ~을 새로 알았어요.」 꼴로 한 문장 쓰고, 그 내용이 글 몇째 줄에 있는지도 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C4","difficulty":4,"kind":"essay","stem":"「소금」을 읽고 새롭게 안 점을 「나는 ~을 새로 알았어요.」 꼴로 한 문장 쓰고, 그 내용이 글 몇째 줄에 있는지도 쓰세요.","answer_guide":{"answer":"예: 나는 소금을 바닷물을 햇볕에 말려서 얻는다는 것을 새로 알았어요. 둘째 줄에 있어요. — 글에 있는 내용과 줄이 맞으면 맞아요.","scoring_points":["글에 적힌 내용인가","「나는 ~을 새로 알았어요」 꼴인가","줄을 바르게 짚었는가"]},"explanation":["글에 있는 것으로.","줄까지 짚으면 지어낸 것이 아님을 알 수 있어요.","몇째 줄?"],"asset":{"type":"passage","lines":["소금은 짠맛이 나는 하얀 알갱이입니다.","소금은 바닷물을 햇볕에 말려서 얻습니다.","음식에 소금을 조금 넣으면 맛이 살아납니다.","배추를 소금에 절이면 오래 두고 먹을 수 있습니다."],"title":"「소금」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#10','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C2',4,'essay','teacher','내가 아끼는 물건 하나를 골라, 제목만 보고도 무엇을 설명하는지 알 수 있게 제목을 짓고, 그 물건을 설명하는 문장을 두 개 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C2","difficulty":4,"kind":"essay","stem":"내가 아끼는 물건 하나를 골라, 제목만 보고도 무엇을 설명하는지 알 수 있게 제목을 짓고, 그 물건을 설명하는 문장을 두 개 쓰세요.","answer_guide":{"answer":"예: 「내 필통」 — 내 필통은 파란 천으로 만든 필통입니다. 내 필통에는 연필 세 자루와 지우개가 들어 있습니다. — 제목에 물건 이름이 있고 문장마다 그 물건이 나오면 맞아요.","scoring_points":["제목에 설명할 물건이 들어 있는가","문장마다 그 물건이 되풀이 나오는가","어떤 것인지나 무엇을 하는지를 알려 주는가"]},"explanation":["제목 = 설명할 것.","문장마다 같은 낱말로 이어 가요.","읽는 사람이 무엇에 대한 글인지 바로 알게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#1','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',1,'mc','auto','이 글 전체가 설명하는 것은 무엇인가요?',ARRAY['K1-2-u7-X04','K1-2-u7-X03']::text[],true,'{"seq":1,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"이 글 전체가 설명하는 것은 무엇인가요?","options":[{"t":"동물들이 사는 집","correct":true},{"t":"까치","mis":"K1-2-u7-X04"},{"t":"잠자는 시간","mis":"K1-2-u7-X03"}],"explanation":["세 문단을 합치면 동물마다 사는 집 이야기예요.","까치는 한 문단, 잠은 제목에만 있어요.","문단 셋을 합쳐요."],"asset":{"type":"passage","lines":["까치는 나뭇가지를 모아 높은 나무 위에 집을 짓습니다.","두더지는 땅속에 굴을 길게 파고 삽니다.","비버는 나무를 갉아 물 위에 집을 짓습니다."],"title":"「어디에서 잠을 잘까?」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이 글 전체가 설명하는 것은 무엇인가요?","options":[{"t":"씨앗이 멀리 퍼지는 방법","correct":true},{"t":"단풍나무","mis":"K1-2-u7-X04"},{"t":"여행을 떠나는 사람","mis":"K1-2-u7-X03"}],"explanation":["세 문단을 합치면 씨앗이 퍼지는 방법이에요.","단풍나무는 한 문단, 여행은 제목에서 떠올린 것이에요.","문단 셋을 합쳐요."],"asset":{"type":"passage","lines":["단풍나무 씨앗은 날개가 있어 바람을 타고 빙글빙글 날아갑니다.","봉숭아 씨앗은 꼬투리가 톡 터지면서 멀리 튀어 나갑니다.","야자 열매는 물에 둥둥 떠서 먼 바닷가까지 갑니다."],"title":"「멀리멀리 떠나요」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#2','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',1,'mc','auto','이 글은 무엇을 설명하나요?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":2,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"이 글은 무엇을 설명하나요?","options":[{"t":"개미","correct":true},{"t":"일꾼","mis":"K1-2-u7-X03"},{"t":"먹이","mis":"K1-2-u7-X04"}],"explanation":["세 문단 모두 개미 이야기예요.","일꾼은 제목에만, 먹이는 한 문단에만 나와요.","제목만 보지 않아요."],"asset":{"type":"passage","lines":["개미는 땅속에 길을 내고 여러 개의 방을 만듭니다.","개미는 자기 몸보다 큰 먹이도 여럿이 함께 들어 옮깁니다.","개미는 더듬이를 맞대어 서로 소식을 전합니다."],"title":"「작아도 힘센 일꾼」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#3','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',1,'mc','auto','제목에 설명하는 것이 나오지 않을 때 어떻게 찾으면 좋을까요?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"제목에 설명하는 것이 나오지 않을 때 어떻게 찾으면 좋을까요?","options":[{"t":"문단마다 무엇을 말하는지 보고 합쳐서 생각해요","correct":true},{"t":"제목 낱말을 그대로 답해요","mis":"K1-2-u7-X03"},{"t":"첫 문단만 보고 답해요","mis":"K1-2-u7-X04"}],"explanation":["문단 → 합치기.","제목 낱말이나 첫 문단만으로는 안 돼요.","제목 → 문단 → 합치기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#4','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C4',1,'mc','auto','이 글을 읽고 새롭게 안 점으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X06','K1-2-u7-X07']::text[],true,'{"seq":4,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"이 글을 읽고 새롭게 안 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"봉숭아 씨앗은 꼬투리가 터지면서 튀어 나간다는 것","correct":true},{"t":"단풍나무 씨앗은 물에 떠서 간다는 것","mis":"K1-2-u7-X06"},{"t":"씨앗은 모두 새가 옮겨 준다는 것","mis":"K1-2-u7-X07"}],"explanation":["둘째 문단에 있어요.","물에 뜨는 것은 야자 열매, 새 이야기는 없어요.","그 문단을 짚어요."],"asset":{"type":"passage","lines":["단풍나무 씨앗은 날개가 있어 바람을 타고 빙글빙글 날아갑니다.","봉숭아 씨앗은 꼬투리가 톡 터지면서 멀리 튀어 나갑니다.","야자 열매는 물에 둥둥 떠서 먼 바닷가까지 갑니다."],"title":"「멀리멀리 떠나요」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이 글을 읽고 새롭게 안 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"개미는 더듬이를 맞대어 소식을 전한다는 것","correct":true},{"t":"개미는 혼자서만 먹이를 옮긴다는 것","mis":"K1-2-u7-X06"},{"t":"개미는 나무 위에 집을 짓는다는 것","mis":"K1-2-u7-X07"}],"explanation":["셋째 문단에 있어요.","여럿이 함께 옮기고, 땅속에 길을 내요.","그 문단을 짚어요."],"asset":{"type":"passage","lines":["개미는 땅속에 길을 내고 여러 개의 방을 만듭니다.","개미는 자기 몸보다 큰 먹이도 여럿이 함께 들어 옮깁니다.","개미는 더듬이를 맞대어 서로 소식을 전합니다."],"title":"「작아도 힘센 일꾼」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#5','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',2,'match','auto','동물과 그 동물이 사는 집을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u7-C3","difficulty":2,"kind":"match","stem":"동물과 그 동물이 사는 집을 선으로 이어 보세요.","pairs":[{"l":"까치","r":"높은 나무 위 나뭇가지 집"},{"l":"두더지","r":"땅속에 길게 판 굴"},{"l":"비버","r":"물 위에 지은 나무 집"}],"mis":"K1-2-u7-X06","explanation":["동물마다 집이 달라요.","까치 · 두더지 · 비버.","문단을 하나씩 짚어요."],"asset":{"type":"passage","lines":["까치는 나뭇가지를 모아 높은 나무 위에 집을 짓습니다.","두더지는 땅속에 굴을 길게 파고 삽니다.","비버는 나무를 갉아 물 위에 집을 짓습니다."],"title":"「어디에서 잠을 잘까?」"},"variant_rule":{"alt":[{"stem":"물건과 그 소리가 알려 주는 것을 선으로 이어 보세요.","pairs":[{"l":"초인종","r":"손님이 왔어요"},{"l":"구급차","r":"길을 비켜 주세요"},{"l":"전자레인지","r":"음식이 다 데워졌어요"}],"explanation":["물건마다 알리는 것이 달라요.","띵동 · 삐뽀 · 땡.","문단을 하나씩 짚어요."],"asset":{"type":"passage","lines":["초인종은 띵동 소리로 손님이 왔다고 알립니다.","구급차는 삐뽀삐뽀 소리로 길을 비켜 달라고 알립니다.","전자레인지는 땡 소리로 음식이 다 데워졌다고 알립니다."],"title":"「띵동, 삐뽀, 땡!」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#6','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',2,'mc','auto','세 문단이 모두 말하고 있는 것은 무엇인가요?',ARRAY['K1-2-u7-X06','K1-2-u7-X07']::text[],false,'{"seq":6,"concept":"K1-2-u7-C3","difficulty":2,"kind":"mc","stem":"세 문단이 모두 말하고 있는 것은 무엇인가요?","options":[{"t":"소리로 무엇인가를 알려 준다","correct":true},{"t":"모두 부엌에 있는 물건이다","mis":"K1-2-u7-X06"},{"t":"모두 시끄러워서 나쁜 물건이다","mis":"K1-2-u7-X07"}],"explanation":["셋 다 소리로 알려 줘요.","구급차는 부엌에 없고, 나쁘다는 말은 없어요.","공통점을 찾아요."],"asset":{"type":"passage","lines":["초인종은 띵동 소리로 손님이 왔다고 알립니다.","구급차는 삐뽀삐뽀 소리로 길을 비켜 달라고 알립니다.","전자레인지는 땡 소리로 음식이 다 데워졌다고 알립니다."],"title":"「띵동, 삐뽀, 땡!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#7','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',2,'ox','auto','제목 「작아도 힘센 일꾼」만 보고 「일꾼」을 설명하는 글이라고 답하면 맞아요.',ARRAY['K1-2-u7-X03']::text[],true,'{"seq":7,"concept":"K1-2-u7-C3","difficulty":2,"kind":"ox","stem":"제목 「작아도 힘센 일꾼」만 보고 「일꾼」을 설명하는 글이라고 답하면 맞아요.","answer":"X","reason_options":[{"t":"문단을 읽어 보면 개미를 설명하는 글이니까","correct":true},{"t":"제목에 있는 낱말이 곧 답이니까","mis":"K1-2-u7-X03"}],"mis":"K1-2-u7-X03","explanation":["제목은 실마리일 뿐이에요.","문단까지 읽어야 해요.","제목 → 문단 → 합치기."],"asset":{"type":"passage","lines":["개미는 땅속에 길을 내고 여러 개의 방을 만듭니다.","개미는 자기 몸보다 큰 먹이도 여럿이 함께 들어 옮깁니다.","개미는 더듬이를 맞대어 서로 소식을 전합니다."],"title":"「작아도 힘센 일꾼」"},"variant_rule":{"alt":[{"stem":"제목 「어디에서 잠을 잘까?」만 보고 「잠」을 설명하는 글이라고 답하면 맞아요.","answer":"X","reason_options":[{"t":"문단을 읽어 보면 동물들이 사는 집을 설명하는 글이니까","correct":true},{"t":"제목에 있는 낱말이 곧 답이니까","mis":"K1-2-u7-X03"}],"explanation":["제목은 실마리일 뿐이에요.","문단까지 읽어야 해요.","제목 → 문단 → 합치기."],"asset":{"type":"passage","lines":["까치는 나뭇가지를 모아 높은 나무 위에 집을 짓습니다.","두더지는 땅속에 굴을 길게 파고 삽니다.","비버는 나무를 갉아 물 위에 집을 짓습니다."],"title":"「어디에서 잠을 잘까?」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#8','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C4',2,'mc','auto','시아가 이 글을 읽고 「두더지는 나무 위에 산대.」 했어요. 시아에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":8,"concept":"K1-2-u7-C4","difficulty":2,"kind":"mc","stem":"시아가 이 글을 읽고 「두더지는 나무 위에 산대.」 했어요. 시아에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"둘째 문단을 다시 봐, 두더지는 땅속에 굴을 파고 살아.","correct":true},{"t":"맞아, 두더지는 나무 위에 살아.","mis":"K1-2-u7-X06"},{"t":"까치와 두더지는 같은 곳에 살아.","mis":"K1-2-u7-X06"}],"explanation":["나무 위는 까치예요.","두 동물을 섞으면 글과 달라져요.","그 문단을 짚어요."],"asset":{"type":"passage","lines":["까치는 나뭇가지를 모아 높은 나무 위에 집을 짓습니다.","두더지는 땅속에 굴을 길게 파고 삽니다.","비버는 나무를 갉아 물 위에 집을 짓습니다."],"title":"「어디에서 잠을 잘까?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
