INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#10','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',3,'error','auto','설명하는 것을 찾는 방법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#1','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',2,'mc','auto','이 글 전체가 설명하는 것은 무엇인가요?',ARRAY['K1-2-u7-X04','K1-2-u7-X03']::text[],false,'{"seq":1,"concept":"K1-2-u7-C3","difficulty":2,"kind":"mc","stem":"이 글 전체가 설명하는 것은 무엇인가요?","options":[{"t":"소리로 알려 주는 물건들","correct":true},{"t":"구급차","mis":"K1-2-u7-X04"},{"t":"띵동","mis":"K1-2-u7-X03"}],"explanation":["세 문단을 합치면 소리로 알려 주는 물건들이에요.","구급차는 한 문단, 띵동은 제목의 소리예요.","문단을 합쳐요."],"asset":{"type":"passage","lines":["초인종은 띵동 소리로 손님이 왔다고 알립니다.","구급차는 삐뽀삐뽀 소리로 길을 비켜 달라고 알립니다.","전자레인지는 땡 소리로 음식이 다 데워졌다고 알립니다."],"title":"「띵동, 삐뽀, 땡!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#2','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',2,'match','auto','씨앗과 멀리 퍼지는 방법을 선으로 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"K1-2-u7-C3","difficulty":2,"kind":"match","stem":"씨앗과 멀리 퍼지는 방법을 선으로 이어 보세요.","pairs":[{"l":"단풍나무 씨앗","r":"날개로 바람을 타고 날아가요"},{"l":"봉숭아 씨앗","r":"꼬투리가 터지며 튀어 나가요"},{"l":"야자 열매","r":"물에 떠서 바닷가까지 가요"}],"mis":"K1-2-u7-X06","explanation":["씨앗마다 방법이 달라요.","날기 · 튀기 · 뜨기.","문단을 짚어요."],"asset":{"type":"passage","lines":["단풍나무 씨앗은 날개가 있어 바람을 타고 빙글빙글 날아갑니다.","봉숭아 씨앗은 꼬투리가 톡 터지면서 멀리 튀어 나갑니다.","야자 열매는 물에 둥둥 떠서 먼 바닷가까지 갑니다."],"title":"「멀리멀리 떠나요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#3','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',3,'mc','auto','제목 「작아도 힘센 일꾼」에서 「일꾼」은 누구를 가리키나요?',ARRAY['K1-2-u7-X03','K1-2-u7-X07']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":3,"kind":"mc","stem":"제목 「작아도 힘센 일꾼」에서 「일꾼」은 누구를 가리키나요?","options":[{"t":"부지런히 일하는 개미","correct":true},{"t":"개미를 부리는 사람","mis":"K1-2-u7-X03"},{"t":"먹이를 나르는 수레","mis":"K1-2-u7-X07"}],"explanation":["길을 내고 먹이를 나르는 개미를 일꾼에 빗댔어요.","사람이나 수레는 글에 없어요.","제목은 실마리."],"asset":{"type":"passage","lines":["개미는 땅속에 길을 내고 여러 개의 방을 만듭니다.","개미는 자기 몸보다 큰 먹이도 여럿이 함께 들어 옮깁니다.","개미는 더듬이를 맞대어 서로 소식을 전합니다."],"title":"「작아도 힘센 일꾼」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#4','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C4',3,'error','auto','「멀리멀리 떠나요」를 읽고 새롭게 안 점을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#5','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',3,'ox','auto','한 문단에만 나온 동물(두더지)을 글 전체가 설명하는 것으로 답해도 맞아요.',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":5,"concept":"K1-2-u7-C3","difficulty":3,"kind":"ox","stem":"한 문단에만 나온 동물(두더지)을 글 전체가 설명하는 것으로 답해도 맞아요.","answer":"X","reason_options":[{"t":"글 전체는 문단 셋을 합쳐야 알 수 있으니까","correct":true},{"t":"가장 재미있는 문단이 글 전체니까","mis":"K1-2-u7-X04"}],"mis":"K1-2-u7-X04","explanation":["한 문단은 한 부분이에요.","합쳐야 전체가 보여요.","모든 문단에 걸치는 것."],"asset":{"type":"passage","lines":["까치는 나뭇가지를 모아 높은 나무 위에 집을 짓습니다.","두더지는 땅속에 굴을 길게 파고 삽니다.","비버는 나무를 갉아 물 위에 집을 짓습니다."],"title":"「어디에서 잠을 잘까?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#6','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',3,'mc','auto','제목이 똑같이 「겨울」인 두 글이 있어요. 하나는 눈썰매 타는 방법을, 하나는 겨울에 피는 꽃을 알려 줘요. 바르게 말한 것은 어느 것인가요?',ARRAY['K1-2-u7-X03']::text[],false,'{"seq":6,"concept":"K1-2-u7-C3","difficulty":3,"kind":"mc","stem":"제목이 똑같이 「겨울」인 두 글이 있어요. 하나는 눈썰매 타는 방법을, 하나는 겨울에 피는 꽃을 알려 줘요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"제목이 같아도 설명하는 것은 다를 수 있어요","correct":true},{"t":"제목이 같으니 설명하는 것도 같아요","mis":"K1-2-u7-X03"},{"t":"두 글 모두 날씨를 설명해요","mis":"K1-2-u7-X03"}],"explanation":["설명하는 것은 글을 읽어야 알아요.","제목만 보면 둘을 가를 수 없어요.","제목은 실마리일 뿐."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#7','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C4',3,'mc','auto','「띵동, 삐뽀, 땡!」을 읽고 새롭게 안 점을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K1-2-u7-X07']::text[],false,'{"seq":7,"concept":"K1-2-u7-C4","difficulty":3,"kind":"mc","stem":"「띵동, 삐뽀, 땡!」을 읽고 새롭게 안 점을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"구급차가 삐뽀삐뽀 소리를 내는 것은 길을 비켜 달라는 뜻이라는 것을 알았어요.","correct":true},{"t":"구급차는 빨간색이라는 것을 알았어요.","mis":"K1-2-u7-X07"},{"t":"소리가 나는 물건은 모두 위험하다는 것을 알았어요.","mis":"K1-2-u7-X07"}],"explanation":["둘째 문단에 있어요.","색깔이나 「모두 위험」은 글에 없어요.","글에 있는 것으로."],"asset":{"type":"passage","lines":["초인종은 띵동 소리로 손님이 왔다고 알립니다.","구급차는 삐뽀삐뽀 소리로 길을 비켜 달라고 알립니다.","전자레인지는 땡 소리로 음식이 다 데워졌다고 알립니다."],"title":"「띵동, 삐뽀, 땡!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#8','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',4,'sa','auto','제목을 가린 글이에요. 문단 셋을 합쳐 빈칸에 알맞은 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#9','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C4',4,'essay','teacher','「어디에서 잠을 잘까?」를 읽고 새롭게 안 점을 한 문장 쓰고, 그 동물이 왜 그런 곳에 집을 짓는다고 생각하는지 내 생각을 한 문장 더 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C4","difficulty":4,"kind":"essay","stem":"「어디에서 잠을 잘까?」를 읽고 새롭게 안 점을 한 문장 쓰고, 그 동물이 왜 그런 곳에 집을 짓는다고 생각하는지 내 생각을 한 문장 더 쓰세요.","answer_guide":{"answer":"예: 비버는 나무를 갉아 물 위에 집을 짓는다는 것을 알았어요. 물 위에 있으면 다른 동물이 쉽게 오지 못해서 그런 것 같아요. — 글에서 안 점과 「~것 같아요」 내 생각이 나뉘어 있으면 맞아요.","scoring_points":["새롭게 안 점이 글에 적힌 내용인가","동물과 집을 바르게 이었는가","내 생각을 「~것 같아요」처럼 나누어 썼는가"]},"explanation":["안 점은 글에서, 생각은 내 말로.","둘을 섞지 않아요.","「~것 같아요」."],"asset":{"type":"passage","lines":["까치는 나뭇가지를 모아 높은 나무 위에 집을 짓습니다.","두더지는 땅속에 굴을 길게 파고 삽니다.","비버는 나무를 갉아 물 위에 집을 짓습니다."],"title":"「어디에서 잠을 잘까?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#10','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',4,'essay','teacher','제목 → 문단 → 합치기 차례로 「띵동, 삐뽀, 땡!」이 무엇을 설명하는지 찾아 가는 과정을 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C3","difficulty":4,"kind":"essay","stem":"제목 → 문단 → 합치기 차례로 「띵동, 삐뽀, 땡!」이 무엇을 설명하는지 찾아 가는 과정을 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 제목만 봐서는 무엇인지 몰랐어요. 문단을 보니 초인종, 구급차, 전자레인지가 나왔어요. 셋을 합치니 소리로 알려 주는 물건들을 설명하는 글이었어요. — 세 걸음이 차례로 있으면 맞아요.","scoring_points":["제목만으로는 알 수 없었다는 것을 썼는가","문단마다 나온 것을 썼는가","합쳐서 설명하는 것을 바르게 찾았는가"]},"explanation":["제목 → 문단 → 합치기.","한 걸음씩 문장 하나.","합친 답이 마지막."],"asset":{"type":"passage","lines":["초인종은 띵동 소리로 손님이 왔다고 알립니다.","구급차는 삐뽀삐뽀 소리로 길을 비켜 달라고 알립니다.","전자레인지는 땡 소리로 음식이 다 데워졌다고 알립니다."],"title":"「띵동, 삐뽀, 땡!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#1','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',1,'mc','auto','재윤이에게 언제 있었던 일인가요?',ARRAY['K1-2-u7-X06','K1-2-u7-X08']::text[],true,'{"seq":1,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"재윤이에게 언제 있었던 일인가요?","options":[{"t":"지난 일요일","correct":true},{"t":"오늘 아침","mis":"K1-2-u7-X06"},{"t":"다음 주","mis":"K1-2-u7-X08"}],"explanation":["첫째 줄에 「지난 일요일」이 있어요.","다음 주는 아직 오지 않은 때예요.","언제 칸."],"asset":{"type":"passage","lines":["지난 일요일, 공원에서 두발자전거를 탔어요.","아빠가 뒤에서 안장을 잡아 주셔서 든든했어요.","한참 가다 돌아보니 아빠가 저 멀리 서 계셨어요.","깜짝 놀랐지만 넘어지지 않고 끝까지 갔어요.","혼자 해냈다는 생각에 가슴이 두근두근 벅찼어요."],"title":"재윤이가 겪은 일"},"variant_rule":{"alt":[{"stem":"건우에게 언제 있었던 일인가요?","options":[{"t":"오늘 아침","correct":true},{"t":"어제 저녁","mis":"K1-2-u7-X06"},{"t":"내일 아침","mis":"K1-2-u7-X08"}],"explanation":["첫째 줄에 「오늘 아침」이 있어요.","내일은 아직 오지 않은 때예요.","언제 칸."],"asset":{"type":"passage","lines":["오늘 아침, 부엌에서 처음으로 달걀을 깨 보았어요.","달걀을 손에 드니 두근두근 설렜어요.","톡 쳤는데 껍데기 조각이 그릇에 빠져서 속상했어요.","숟가락으로 살살 건져 내니 엄마가 손뼉을 쳐 주셨어요.","내 손으로 한 첫 요리라서 뿌듯했어요."],"title":"건우가 겪은 일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#2','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',1,'mc','auto','재윤이에게 있었던 일은 어디에서 있었나요?',ARRAY['K1-2-u7-X06']::text[],true,'{"seq":2,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"재윤이에게 있었던 일은 어디에서 있었나요?","options":[{"t":"공원","correct":true},{"t":"학교 운동장","mis":"K1-2-u7-X06"},{"t":"자전거 가게","mis":"K1-2-u7-X06"}],"explanation":["첫째 줄에 「공원에서」가 있어요.","운동장·가게는 글에 없어요.","어디에서 칸."],"asset":{"type":"passage","lines":["지난 일요일, 공원에서 두발자전거를 탔어요.","아빠가 뒤에서 안장을 잡아 주셔서 든든했어요.","한참 가다 돌아보니 아빠가 저 멀리 서 계셨어요.","깜짝 놀랐지만 넘어지지 않고 끝까지 갔어요.","혼자 해냈다는 생각에 가슴이 두근두근 벅찼어요."],"title":"재윤이가 겪은 일"},"variant_rule":{"alt":[{"stem":"예린이에게 있었던 일은 어디에서 있었나요?","options":[{"t":"학교 현관","correct":true},{"t":"할머니 집","mis":"K1-2-u7-X06"},{"t":"버스 정류장","mis":"K1-2-u7-X06"}],"explanation":["첫째 줄에 「현관에」가 있어요.","할머니 집·정류장은 글에 없어요.","어디에서 칸."],"asset":{"type":"passage","lines":["어제 학교가 끝나고 현관에 서 있었어요.","비가 쏟아지는데 우산이 없어서 막막했어요.","친구들이 하나둘 가 버리자 서운해서 눈물이 날 것 같았어요.","그때 할머니가 노란 우산을 들고 오셨어요.","할머니 손을 꼭 잡으니 마음이 따뜻해졌어요."],"title":"예린이가 겪은 일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#3','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C6',1,'mc','auto','끝까지 혼자 간 뒤 재윤이의 마음은 어떠했나요?',ARRAY['K1-2-u7-X13']::text[],false,'{"seq":3,"concept":"K1-2-u7-C6","difficulty":1,"kind":"mc","stem":"끝까지 혼자 간 뒤 재윤이의 마음은 어떠했나요?","options":[{"t":"혼자 해내서 가슴이 벅찼어요","correct":true},{"t":"지루하고 귀찮았어요","mis":"K1-2-u7-X13"},{"t":"화가 났어요","mis":"K1-2-u7-X13"}],"explanation":["다섯째 줄에 있어요.","지루함·화남은 장면과 어울리지 않아요.","그 줄의 마음말."],"asset":{"type":"passage","lines":["지난 일요일, 공원에서 두발자전거를 탔어요.","아빠가 뒤에서 안장을 잡아 주셔서 든든했어요.","한참 가다 돌아보니 아빠가 저 멀리 서 계셨어요.","깜짝 놀랐지만 넘어지지 않고 끝까지 갔어요.","혼자 해냈다는 생각에 가슴이 두근두근 벅찼어요."],"title":"재윤이가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#4','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',1,'mc','auto','겪은 일을 정리하는 네 칸으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X10']::text[],false,'{"seq":4,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"겪은 일을 정리하는 네 칸으로 알맞은 것은 어느 것인가요?","options":[{"t":"언제 · 어디에서 · 무슨 일 · 그때 마음","correct":true},{"t":"언제 · 어디에서 · 글자 수 · 친구 이름","mis":"K1-2-u7-X10"},{"t":"제목 · 그림 · 색깔 · 점수","mis":"K1-2-u7-X10"}],"explanation":["네 칸을 채우면 겪은 일이 잘 드러나요.","글자 수·점수는 정리할 것이 아니에요.","때 · 곳 · 일 · 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#5','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C6',2,'match','auto','장면과 그때 재윤이의 마음을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u7-C6","difficulty":2,"kind":"match","stem":"장면과 그때 재윤이의 마음을 선으로 이어 보세요.","pairs":[{"l":"아빠가 안장을 잡아 줄 때","r":"든든했어요"},{"l":"아빠가 멀리 서 계신 것을 봤을 때","r":"깜짝 놀랐어요"},{"l":"끝까지 혼자 갔을 때","r":"가슴이 벅찼어요"}],"mis":"K1-2-u7-X13","explanation":["장면이 바뀌면 마음도 바뀌어요.","든든 → 놀람 → 벅참.","줄을 짚어요."],"asset":{"type":"passage","lines":["지난 일요일, 공원에서 두발자전거를 탔어요.","아빠가 뒤에서 안장을 잡아 주셔서 든든했어요.","한참 가다 돌아보니 아빠가 저 멀리 서 계셨어요.","깜짝 놀랐지만 넘어지지 않고 끝까지 갔어요.","혼자 해냈다는 생각에 가슴이 두근두근 벅찼어요."],"title":"재윤이가 겪은 일"},"variant_rule":{"alt":[{"stem":"장면과 그때 건우의 마음을 선으로 이어 보세요.","pairs":[{"l":"달걀을 처음 손에 들었을 때","r":"설렜어요"},{"l":"껍데기가 그릇에 빠졌을 때","r":"속상했어요"},{"l":"첫 요리를 마쳤을 때","r":"뿌듯했어요"}],"explanation":["장면이 바뀌면 마음도 바뀌어요.","설렘 → 속상 → 뿌듯.","줄을 짚어요."],"asset":{"type":"passage","lines":["오늘 아침, 부엌에서 처음으로 달걀을 깨 보았어요.","달걀을 손에 드니 두근두근 설렜어요.","톡 쳤는데 껍데기 조각이 그릇에 빠져서 속상했어요.","숟가락으로 살살 건져 내니 엄마가 손뼉을 쳐 주셨어요.","내 손으로 한 첫 요리라서 뿌듯했어요."],"title":"건우가 겪은 일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#6','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',2,'mc','auto','겪은 일을 정리할 때 살펴보지 않아도 되는 것은 어느 것인가요?',ARRAY['K1-2-u7-X10']::text[],false,'{"seq":6,"concept":"K1-2-u7-C5","difficulty":2,"kind":"mc","stem":"겪은 일을 정리할 때 살펴보지 않아도 되는 것은 어느 것인가요?","options":[{"t":"친구보다 글을 길게 썼는지","correct":true},{"t":"어디에서 있었던 일인지","mis":"K1-2-u7-X10"},{"t":"그때 마음이 어떠했는지","mis":"K1-2-u7-X10"}],"explanation":["남과 견주는 것은 정리할 것이 아니에요.","어디에서와 마음은 꼭 넣어요.","네 칸만."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#7','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',2,'ox','auto','겪은 일은 생일이나 여행처럼 특별한 날에 있었던 일만 쓸 수 있어요.',ARRAY['K1-2-u7-X09']::text[],true,'{"seq":7,"concept":"K1-2-u7-C5","difficulty":2,"kind":"ox","stem":"겪은 일은 생일이나 여행처럼 특별한 날에 있었던 일만 쓸 수 있어요.","answer":"X","reason_options":[{"t":"날마다 있는 일도 마음이 움직였다면 좋은 글감이 되니까","correct":true},{"t":"특별해야 읽는 사람이 좋아하니까","mis":"K1-2-u7-X09"}],"mis":"K1-2-u7-X09","explanation":["달걀 깨기, 이 빠지기도 글감이에요.","특별하지 않아도 돼요.","마음이 움직인 일."],"variant_rule":{"alt":[{"stem":"급식을 먹다 이가 빠진 일처럼 학교에서 있었던 일도 글감이 될 수 있어요.","answer":"O","reason_options":[{"t":"마음이 움직인 일이면 어떤 일이든 글감이 되니까","correct":true},{"t":"학교에서 있었던 일은 모두 같아서 쓸 게 없으니까","mis":"K1-2-u7-X09"}],"explanation":["날마다 있는 곳에서도 글감이 생겨요.","마음이 움직였는지 보세요.","오늘 일도 글감."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#8','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C6',2,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u7-X12']::text[],true,'{"seq":8,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"설렜다","correct":true},{"t":"달려갔다","mis":"K1-2-u7-X12"},{"t":"문을 열었다","mis":"K1-2-u7-X12"}],"explanation":["「설렜다」는 마음이 느낀 것이에요.","달려가기, 문 열기는 몸이 한 일이에요.","몸이 한 것? 마음이 느낀 것?"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 마음을 나타내는 말은 어느 것인가요?","options":[{"t":"서운했다","correct":true},{"t":"건져 냈다","mis":"K1-2-u7-X12"},{"t":"자리에 앉았다","mis":"K1-2-u7-X12"}],"explanation":["「서운했다」는 마음이 느낀 것이에요.","건져 내기, 앉기는 몸이 한 일이에요.","몸이 한 것? 마음이 느낀 것?"],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#9','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C6',2,'mc','auto','마음이 더 잘 드러난 말은 어느 것인가요?',ARRAY['K1-2-u7-X11']::text[],false,'{"seq":9,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"마음이 더 잘 드러난 말은 어느 것인가요?","options":[{"t":"혼자 해냈다는 생각에 가슴이 두근두근 벅찼다.","correct":true},{"t":"그냥 좋았다.","mis":"K1-2-u7-X11"},{"t":"재미있었다.","mis":"K1-2-u7-X11"}],"explanation":["어떤 마음인지, 왜 그런지가 보여요.","「그냥 좋았다·재미있었다」는 어떤 마음인지 흐려요.","까닭을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#10','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',3,'error','auto','예린이가 겪은 일을 네 칸으로 정리했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#1','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C5',2,'mc','auto','예린이에게 있었던 「무슨 일」로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":1,"concept":"K1-2-u7-C5","difficulty":2,"kind":"mc","stem":"예린이에게 있었던 「무슨 일」로 알맞은 것은 어느 것인가요?","options":[{"t":"비가 오는데 우산이 없어 기다리다가 할머니가 우산을 가져오셨어요","correct":true},{"t":"할머니 댁에 놀러 갔어요","mis":"K1-2-u7-X06"},{"t":"비를 맞으며 신나게 뛰어놀았어요","mis":"K1-2-u7-X06"}],"explanation":["둘째~넷째 줄이 무슨 일이에요.","놀러 가거나 뛰어논 일은 없어요.","줄을 짚어요."],"asset":{"type":"passage","lines":["어제 학교가 끝나고 현관에 서 있었어요.","비가 쏟아지는데 우산이 없어서 막막했어요.","친구들이 하나둘 가 버리자 서운해서 눈물이 날 것 같았어요.","그때 할머니가 노란 우산을 들고 오셨어요.","할머니 손을 꼭 잡으니 마음이 따뜻해졌어요."],"title":"예린이가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#2','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C6',2,'match','auto','장면과 그때 예린이의 마음을 선으로 이어 보세요.','{}'::text[],true,'{"seq":2,"concept":"K1-2-u7-C6","difficulty":2,"kind":"match","stem":"장면과 그때 예린이의 마음을 선으로 이어 보세요.","pairs":[{"l":"우산이 없는 것을 알았을 때","r":"막막했어요"},{"l":"친구들이 가 버렸을 때","r":"서운했어요"},{"l":"할머니 손을 잡았을 때","r":"마음이 따뜻해졌어요"}],"mis":"K1-2-u7-X13","explanation":["장면마다 마음이 달라요.","막막 → 서운 → 따뜻.","줄을 짚어요."],"asset":{"type":"passage","lines":["어제 학교가 끝나고 현관에 서 있었어요.","비가 쏟아지는데 우산이 없어서 막막했어요.","친구들이 하나둘 가 버리자 서운해서 눈물이 날 것 같았어요.","그때 할머니가 노란 우산을 들고 오셨어요.","할머니 손을 꼭 잡으니 마음이 따뜻해졌어요."],"title":"예린이가 겪은 일"},"variant_rule":{"alt":[{"stem":"장면과 그때 아린이의 마음을 선으로 이어 보세요.","pairs":[{"l":"이가 빠져 피가 났을 때","r":"덜컥 겁이 났어요"},{"l":"선생님이 괜찮다고 하셨을 때","r":"마음이 놓였어요"},{"l":"빠진 이를 담아 왔을 때","r":"신기하고 자랑스러웠어요"}],"explanation":["장면마다 마음이 달라요.","겁 → 놓임 → 자랑.","줄을 짚어요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 사과를 먹었어요.","사각 깨무는데 흔들리던 앞니가 쏙 빠졌어요.","피가 조금 나서 덜컥 겁이 났어요.","선생님이 휴지를 주시며 괜찮다고 하셔서 마음이 놓였어요.","빠진 이를 작은 통에 담아 오니 신기하고 자랑스러웠어요."],"title":"아린이가 겪은 일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#3','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C6',3,'mc','auto','아린이의 「덜컥 겁이 났어요」와 가장 비슷한 마음은 어느 것인가요?',ARRAY['K1-2-u7-X13']::text[],false,'{"seq":3,"concept":"K1-2-u7-C6","difficulty":3,"kind":"mc","stem":"아린이의 「덜컥 겁이 났어요」와 가장 비슷한 마음은 어느 것인가요?","options":[{"t":"무서웠어요","correct":true},{"t":"신났어요","mis":"K1-2-u7-X13"},{"t":"졸렸어요","mis":"K1-2-u7-X13"}],"explanation":["피가 나서 무서운 마음이에요.","신나거나 졸린 장면이 아니에요.","장면을 떠올려요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 사과를 먹었어요.","사각 깨무는데 흔들리던 앞니가 쏙 빠졌어요.","피가 조금 나서 덜컥 겁이 났어요.","선생님이 휴지를 주시며 괜찮다고 하셔서 마음이 놓였어요.","빠진 이를 작은 통에 담아 오니 신기하고 자랑스러웠어요."],"title":"아린이가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#4','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C6',3,'error','auto','마음을 나타내는 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#5','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C5',3,'ox','auto','겪은 일을 네 칸으로 정리하면 글을 쓸 때 무엇을 먼저 쓸지 차례가 잡혀요.',ARRAY['K1-2-u7-X14']::text[],false,'{"seq":5,"concept":"K1-2-u7-C5","difficulty":3,"kind":"ox","stem":"겪은 일을 네 칸으로 정리하면 글을 쓸 때 무엇을 먼저 쓸지 차례가 잡혀요.","answer":"O","reason_options":[{"t":"언제·어디에서 다음에 무슨 일과 마음을 이어 쓰면 되니까","correct":true},{"t":"네 칸은 글을 길게 늘이려고 쓰는 것이니까","mis":"K1-2-u7-X14"}],"mis":"K1-2-u7-X14","explanation":["네 칸이 글의 뼈대가 돼요.","늘이려는 것이 아니에요.","때 · 곳 · 일 · 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#6','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C5',3,'mc','auto','건우가 정리한 겪은 일에서 빠진 칸은 어느 것인가요?',ARRAY['K1-2-u7-X10']::text[],false,'{"seq":6,"concept":"K1-2-u7-C5","difficulty":3,"kind":"mc","stem":"건우가 정리한 겪은 일에서 빠진 칸은 어느 것인가요?","options":[{"t":"어디에서","correct":true},{"t":"언제","mis":"K1-2-u7-X10"},{"t":"그때 마음","mis":"K1-2-u7-X10"}],"explanation":["「부엌에서」가 빠졌어요.","언제와 마음은 있어요.","네 칸을 하나씩 짚어요."],"asset":{"type":"passage","lines":["언제: 오늘 아침","무슨 일: 처음으로 달걀을 깨다가 껍데기를 빠뜨렸어요.","그때 마음: 속상했다가 뿌듯했어요."],"title":"건우가 정리한 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#7','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C5',3,'mc','auto','날마다 있는 일 가운데 겪은 일 글감이 될 수 있는 것은 어느 것인가요?',ARRAY['K1-2-u7-X08']::text[],false,'{"seq":7,"concept":"K1-2-u7-C5","difficulty":3,"kind":"mc","stem":"날마다 있는 일 가운데 겪은 일 글감이 될 수 있는 것은 어느 것인가요?","options":[{"t":"아침에 신발 끈이 풀려 동생이 묶어 준 일","correct":true},{"t":"아직 가 보지 못한 놀이공원","mis":"K1-2-u7-X08"},{"t":"다음 달에 있을 운동회","mis":"K1-2-u7-X08"}],"explanation":["이미 있었던 작은 일도 글감이에요.","놀이공원·운동회는 아직이에요.","있었던 일 + 마음이 움직인 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#8','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C6',4,'sa','auto','건우가 첫 요리를 마친 뒤의 마음을 나타낸 낱말을 글에서 찾아 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u7-C6","difficulty":4,"kind":"sa","stem":"건우가 첫 요리를 마친 뒤의 마음을 나타낸 낱말을 글에서 찾아 쓰세요.","answer":["뿌듯했어요","뿌듯했다","뿌듯하다","뿌듯","뿌듯해요"],"explanation":["다섯째 줄의 「뿌듯했어요」예요.","「손뼉을 쳐 주셨어요」는 엄마가 한 일이에요.","마음말을 찾아요."],"asset":{"type":"passage","lines":["오늘 아침, 부엌에서 처음으로 달걀을 깨 보았어요.","달걀을 손에 드니 두근두근 설렜어요.","톡 쳤는데 껍데기 조각이 그릇에 빠져서 속상했어요.","숟가락으로 살살 건져 내니 엄마가 손뼉을 쳐 주셨어요.","내 손으로 한 첫 요리라서 뿌듯했어요."],"title":"건우가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#9','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C5',4,'essay','teacher','무언가를 처음 해 본 일을 떠올려 네 칸(언제·어디에서·무슨 일·그때 마음)으로 정리해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C5","difficulty":4,"kind":"essay","stem":"무언가를 처음 해 본 일을 떠올려 네 칸(언제·어디에서·무슨 일·그때 마음)으로 정리해 쓰세요.","answer_guide":{"answer":"예: 언제 — 지난 토요일 / 어디에서 — 할머니 댁 마당 / 무슨 일 — 처음으로 닭에게 모이를 주었다 / 그때 마음 — 닭이 손가락을 쫄까 봐 떨렸지만 다 주고 나니 뿌듯했다. — 네 칸이 다 차고 마음에 까닭이 있으면 맞아요.","scoring_points":["이미 있었던 일인가","네 칸을 다 채웠는가","마음에 까닭이 있는가"]},"explanation":["네 칸을 하나씩.","작은 일도 좋아요.","마음은 까닭과 함께."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#10','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C6',4,'essay','teacher','최근에 겪은 일 하나를 골라, 「재미있었다」 대신 까닭이 들어간 다른 마음말로 그때 마음을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C6","difficulty":4,"kind":"essay","stem":"최근에 겪은 일 하나를 골라, 「재미있었다」 대신 까닭이 들어간 다른 마음말로 그때 마음을 쓰세요.","answer_guide":{"answer":"예: 친구와 블록으로 높은 탑을 쌓았는데 마지막 한 칸까지 무너지지 않아서 손에 땀이 날 만큼 짜릿했다. — 「재미있었다」가 아닌 마음말과 까닭이 있으면 맞아요.","scoring_points":["「재미있었다·좋았다」가 아닌 마음말을 썼는가","까닭이 들어 있는가","있었던 일과 마음이 어울리는가"]},"explanation":["다른 마음말 + 까닭.","짜릿했다·두근거렸다·뿌듯했다…","장면에 맞게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#1','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',1,'mc','auto','고구마를 캔 일을 그 자리에 있었던 것처럼 그려지게 쓴 문장은 어느 것인가요?',ARRAY['K1-2-u7-X15']::text[],true,'{"seq":1,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"고구마를 캔 일을 그 자리에 있었던 것처럼 그려지게 쓴 문장은 어느 것인가요?","options":[{"t":"호미로 흙을 살살 긁자 빨간 고구마가 얼굴을 내밀었다.","correct":true},{"t":"고구마를 캤다.","mis":"K1-2-u7-X15"},{"t":"텃밭에 갔다 왔다.","mis":"K1-2-u7-X15"}],"explanation":["무엇을 했고 무엇이 보였는지 눈에 그려져요.","「캤다·갔다 왔다」는 장면이 흐려요.","본 것·한 일을 넣어요."],"variant_rule":{"alt":[{"stem":"눈사람을 만든 일을 그 자리에 있었던 것처럼 그려지게 쓴 문장은 어느 것인가요?","options":[{"t":"장갑 낀 손으로 눈을 굴리자 눈덩이가 점점 커졌다.","correct":true},{"t":"눈사람을 만들었다.","mis":"K1-2-u7-X15"},{"t":"밖에 나갔다 왔다.","mis":"K1-2-u7-X15"}],"explanation":["무엇을 했고 무엇이 보였는지 눈에 그려져요.","「만들었다·나갔다 왔다」는 장면이 흐려요.","본 것·한 일을 넣어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#2','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',1,'mc','auto','겪은 일을 넓게 떠올릴 때 쓰는 네 갈래는 무엇인가요?',ARRAY['K1-2-u7-X16']::text[],false,'{"seq":2,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"겪은 일을 넓게 떠올릴 때 쓰는 네 갈래는 무엇인가요?","options":[{"t":"본 것 · 들은 것 · 한 일 · 느낀 것","correct":true},{"t":"산 것 · 먹은 것 · 잃은 것 · 남은 것","mis":"K1-2-u7-X16"},{"t":"글자 · 줄 · 쪽 · 칸","mis":"K1-2-u7-X16"}],"explanation":["네 갈래로 뻗으면 쓸 거리가 늘어요.","다른 묶음은 겪은 일을 넓혀 주지 않아요.","보고 · 듣고 · 하고 · 느끼고."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#3','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',1,'mc','auto','글감으로 고르기 좋은 일은 어느 것인가요?',ARRAY['K1-2-u7-X16']::text[],false,'{"seq":3,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"글감으로 고르기 좋은 일은 어느 것인가요?","options":[{"t":"지금도 생생하고 누군가에게 꼭 들려주고 싶은 일","correct":true},{"t":"아무 기억이 나지 않는 일","mis":"K1-2-u7-X16"},{"t":"내가 겪지 않은 친구의 일","mis":"K1-2-u7-X16"}],"explanation":["하고 싶은 말이 있어야 글이 살아나요.","기억이 없거나 남의 일은 쓰기 어려워요.","누구에게 들려주고 싶나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#4','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C6',1,'mc','auto','「재미있었다」를 더 잘 바꾼 것은 어느 것인가요?',ARRAY['K1-2-u7-X11']::text[],true,'{"seq":4,"concept":"K1-2-u7-C6","difficulty":1,"kind":"mc","stem":"「재미있었다」를 더 잘 바꾼 것은 어느 것인가요?","options":[{"t":"고구마가 줄줄이 나와서 보물을 찾은 것처럼 신났다.","correct":true},{"t":"아주아주 재미있었다.","mis":"K1-2-u7-X11"},{"t":"재미있고 또 재미있었다.","mis":"K1-2-u7-X11"}],"explanation":["왜 그런지까지 들어 있어요.","「아주아주」만 붙이면 까닭이 없어요.","까닭을 넣어요."],"variant_rule":{"alt":[{"stem":"「좋았다」를 더 잘 바꾼 것은 어느 것인가요?","options":[{"t":"친구가 내 이름을 불러 주어서 어깨가 으쓱했다.","correct":true},{"t":"정말정말 좋았다.","mis":"K1-2-u7-X11"},{"t":"좋고 좋았다.","mis":"K1-2-u7-X11"}],"explanation":["왜 그런지까지 들어 있어요.","「정말정말」만 붙이면 까닭이 없어요.","까닭을 넣어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#5','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',2,'match','auto','겪은 일과 관련 있는 것을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u7-C7","difficulty":2,"kind":"match","stem":"겪은 일과 관련 있는 것을 선으로 이어 보세요.","pairs":[{"l":"바닷가에 간 일","r":"파도 · 갈매기 · 모래성"},{"l":"눈사람을 만든 일","r":"장갑 · 당근 코 · 시린 손"},{"l":"생일잔치를 한 일","r":"초 · 케이크 · 축하 노래"}],"mis":"K1-2-u7-X16","explanation":["일마다 떠오르는 재료가 달라요.","재료를 모으면 글이 풍성해져요.","그 자리에 무엇이 있었나요?"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 겪은 일과 관련 있는 것을 선으로 이어 보세요.","pairs":[{"l":"김장을 도운 일","r":"배추 · 고무장갑 · 빨간 양념"},{"l":"연을 날린 일","r":"바람 · 실 · 높은 하늘"},{"l":"치과에 간 일","r":"하얀 의자 · 윙 소리 · 약 냄새"}],"explanation":["일마다 떠오르는 재료가 달라요.","재료를 모으면 글이 풍성해져요.","그 자리에 무엇이 있었나요?"],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#6','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',2,'ox','auto','하루에 한 일을 모두 늘어놓으면 겪은 일이 잘 드러나는 글이 돼요.',ARRAY['K1-2-u7-X14']::text[],false,'{"seq":6,"concept":"K1-2-u7-C7","difficulty":2,"kind":"ox","stem":"하루에 한 일을 모두 늘어놓으면 겪은 일이 잘 드러나는 글이 돼요.","answer":"X","reason_options":[{"t":"한 가지 일을 자세히 써야 장면이 그려지니까","correct":true},{"t":"많이 쓸수록 잘 쓴 글이니까","mis":"K1-2-u7-X14"}],"mis":"K1-2-u7-X14","explanation":["늘어놓으면 도리어 흐려져요.","하나를 골라 자세히.","어느 장면이 눈에 그려지나요?"],"asset":{"type":"passage","lines":["아침에 일어났다. 밥을 먹었다.","학교에 갔다. 공부를 했다.","집에 왔다. 숙제를 했다.","저녁을 먹고 잠을 잤다."],"title":"루아가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#7','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',2,'mc','auto','겪은 일은 어떤 차례로 쓰면 좋을까요?',ARRAY['K1-2-u7-X17']::text[],false,'{"seq":7,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"겪은 일은 어떤 차례로 쓰면 좋을까요?","options":[{"t":"일이 일어난 차례대로","correct":true},{"t":"생각나는 것부터 섞어서","mis":"K1-2-u7-X17"},{"t":"마음을 맨 처음에 다 쓰고 일은 나중에","mis":"K1-2-u7-X17"}],"explanation":["차례대로 쓰면 읽는 사람이 따라와요.","뒤섞이면 무슨 일인지 헷갈려요.","처음 → 가운데 → 끝."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#8','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',2,'mc','auto','친구 글을 나누어 읽을 때 먼저 할 일은 무엇인가요?',ARRAY['K1-2-u7-X18']::text[],false,'{"seq":8,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"친구 글을 나누어 읽을 때 먼저 할 일은 무엇인가요?","options":[{"t":"좋은 표현을 찾아 칭찬해요","correct":true},{"t":"틀린 글자를 세어요","mis":"K1-2-u7-X18"},{"t":"누구 글이 더 긴지 견주어요","mis":"K1-2-u7-X18"}],"explanation":["좋은 점부터 찾아 줘요.","틀린 글자·길이 견주기가 목적이 아니에요.","어떤 일과 마음이 드러났나?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#9','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',2,'blank','auto','장면이 그려지게 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#10','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',3,'error','auto','겪은 일이 잘 드러난 문장을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#1','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',2,'mc','auto','소미의 글을 겪은 일이 잘 드러나게 고치려면 무엇을 더하면 좋을까요?',ARRAY['K1-2-u7-X14','K1-2-u7-X11']::text[],false,'{"seq":1,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"소미의 글을 겪은 일이 잘 드러나게 고치려면 무엇을 더하면 좋을까요?","options":[{"t":"고구마를 캘 때 본 것과 한 일을 자세히","correct":true},{"t":"다른 날 한 일을 더 늘어놓기","mis":"K1-2-u7-X14"},{"t":"「재미있었다」를 여러 번 쓰기","mis":"K1-2-u7-X11"}],"explanation":["본 것·한 일을 더하면 장면이 생겨요.","늘어놓거나 같은 말을 되풀이하면 그대로예요.","그때 무엇이 보였나요?"],"asset":{"type":"passage","lines":["토요일에 텃밭에 갔다.","고구마를 캤다.","재미있었다."],"title":"소미가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#2','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',2,'match','auto','「바닷가에 간 일」을 네 갈래로 떠올렸어요. 갈래와 내용을 선으로 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"K1-2-u7-C7","difficulty":2,"kind":"match","stem":"「바닷가에 간 일」을 네 갈래로 떠올렸어요. 갈래와 내용을 선으로 이어 보세요.","pairs":[{"l":"본 것","r":"하얗게 부서지는 파도"},{"l":"들은 것","r":"철썩철썩 파도 소리"},{"l":"느낀 것","r":"발가락이 간질간질했다"}],"mis":"K1-2-u7-X16","explanation":["갈래마다 들어갈 것이 달라요.","눈 · 귀 · 마음.","갈래 이름을 물음으로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#3','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',3,'mc','auto','루아의 글을 고쳐 쓸 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K1-2-u7-X14','K1-2-u7-X11']::text[],false,'{"seq":3,"concept":"K1-2-u7-C7","difficulty":3,"kind":"mc","stem":"루아의 글을 고쳐 쓸 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"가장 기억에 남는 일 하나를 골라 자세히 써요","correct":true},{"t":"한 일을 더 많이 늘어놓아요","mis":"K1-2-u7-X14"},{"t":"끝에 「재미있었다」를 붙여요","mis":"K1-2-u7-X11"}],"explanation":["하나를 골라야 장면이 그려져요.","더 늘어놓거나 한마디 붙이는 것은 그대로예요.","하나를 자세히."],"asset":{"type":"passage","lines":["아침에 일어났다. 밥을 먹었다.","학교에 갔다. 공부를 했다.","집에 왔다. 숙제를 했다.","저녁을 먹고 잠을 잤다."],"title":"루아가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#4','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',3,'mc','auto','일이 일어난 차례로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K1-2-u7-X17']::text[],false,'{"seq":4,"concept":"K1-2-u7-C7","difficulty":3,"kind":"mc","stem":"일이 일어난 차례로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"② → ④ → ① → ③","correct":true},{"t":"① → ② → ④ → ③","mis":"K1-2-u7-X17"},{"t":"② → ① → ④ → ③","mis":"K1-2-u7-X17"}],"explanation":["도착 → 쌓기 → 무너짐 → 다짐.","쌓기 전에 무너질 수는 없어요.","처음·가운데·끝."],"asset":{"type":"passage","lines":["① 모래성이 파도에 스르르 무너졌다.","② 아침에 바닷가에 도착했다.","③ 아쉬웠지만 다음에는 더 크게 쌓기로 했다.","④ 모래를 모아 성을 쌓았다."],"title":"차례가 섞인 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#5','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',3,'ox','auto','친구 글을 나누어 읽을 때는 틀린 글자를 찾는 것이 가장 중요해요.',ARRAY['K1-2-u7-X18']::text[],false,'{"seq":5,"concept":"K1-2-u7-C7","difficulty":3,"kind":"ox","stem":"친구 글을 나누어 읽을 때는 틀린 글자를 찾는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"어떤 일이 있었는지와 마음이 드러났는지를 먼저 보니까","correct":true},{"t":"맞춤법이 맞아야 좋은 글이니까","mis":"K1-2-u7-X18"}],"mis":"K1-2-u7-X18","explanation":["좋은 점부터.","틀린 글자는 나중에 함께 고쳐요.","일과 마음이 드러났나?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#6','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C6',3,'mc','auto','「신났다」에 까닭이 들어가게 바꾼 것은 어느 것인가요?',ARRAY['K1-2-u7-X11']::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":3,"kind":"mc","stem":"「신났다」에 까닭이 들어가게 바꾼 것은 어느 것인가요?","options":[{"t":"모래성이 내 키만큼 높아져서 신났다.","correct":true},{"t":"정말 정말 신났다.","mis":"K1-2-u7-X11"},{"t":"신나고 즐겁고 기뻤다.","mis":"K1-2-u7-X11"}],"explanation":["왜 신났는지 보여요.","같은 마음말만 늘어놓으면 까닭이 없어요.","「~해서」를 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#7','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',3,'error','auto','다인이의 글을 나누어 읽고 친구들이 한 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#8','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C6',4,'sa','auto','다인이가 「재미있었다」 대신 쓴 말을 찾아 빈칸에 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#9','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',4,'essay','teacher','겪은 일 하나를 골라, 본 것·들은 것·한 일·느낀 것 가운데 셋 이상을 넣어 세 문장 넘게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C7","difficulty":4,"kind":"essay","stem":"겪은 일 하나를 골라, 본 것·들은 것·한 일·느낀 것 가운데 셋 이상을 넣어 세 문장 넘게 쓰세요.","answer_guide":{"answer":"예: 어제 저녁 아빠와 동네 공원을 걸었다. 가로등 아래에서 귀뚜라미가 또르르 울었다. 아빠 손을 잡고 소리 나는 쪽으로 살금살금 다가갔더니 가슴이 콩닥거렸다. — 세 갈래 이상이 들어 있고 한 가지 일을 자세히 썼으면 맞아요.","scoring_points":["한 가지 일을 골라 썼는가","본 것·들은 것·한 일·느낀 것 가운데 셋 이상이 있는가","일이 일어난 차례대로 썼는가"]},"explanation":["하나를 자세히.","네 갈래에서 셋 이상.","차례대로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#10','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',4,'essay','teacher','소미의 글을 장면이 그려지게 고쳐 쓰세요. 「재미있었다」는 까닭이 들어간 다른 말로 바꾸세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C7","difficulty":4,"kind":"essay","stem":"소미의 글을 장면이 그려지게 고쳐 쓰세요. 「재미있었다」는 까닭이 들어간 다른 말로 바꾸세요.","answer_guide":{"answer":"예: 토요일 아침 텃밭에서 할머니와 고구마를 캤다. 흙을 손으로 헤치자 길쭉한 고구마가 쏙 나왔다. 내가 캔 고구마가 가장 커서 어깨가 으쓱했다. — 본 것·한 일이 더해지고 마음에 까닭이 있으면 맞아요.","scoring_points":["본 것이나 한 일을 더했는가","「재미있었다」를 까닭 있는 다른 마음말로 바꾸었는가","처음 글의 일(고구마 캐기)을 지켰는가"]},"explanation":["장면 + 까닭 있는 마음.","같은 일을 더 자세히.","늘어놓지 않아요."],"asset":{"type":"passage","lines":["토요일에 텃밭에 갔다.","고구마를 캤다.","재미있었다."],"title":"소미가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#1','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',1,'mc','auto','소미가 다인이를 칭찬하는 까닭은 무엇인가요?',ARRAY['K1-2-u7-X19']::text[],true,'{"seq":1,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"소미가 다인이를 칭찬하는 까닭은 무엇인가요?","options":[{"t":"엉킨 줄넘기 줄을 같이 풀어 주어서","correct":true},{"t":"줄넘기를 가장 잘해서","mis":"K1-2-u7-X19"},{"t":"키가 커서","mis":"K1-2-u7-X19"}],"explanation":["둘째 줄에 다인이가 한 일이 있어요.","잘하는 것, 키는 글에 없어요.","한 일을 찾아요."],"asset":{"type":"passage","lines":["오늘 체육 시간에 내 줄넘기 줄이 엉켜 버렸다.","짝 다인이가 엉킨 줄을 같이 풀어 주었다.","덕분에 끝까지 넘을 수 있어서 고마웠다."],"title":"소미가 쓴 칭찬하는 글"},"variant_rule":{"alt":[{"stem":"루아가 시아를 칭찬하는 까닭은 무엇인가요?","options":[{"t":"엎은 물을 같이 닦아 주어서","correct":true},{"t":"그림을 가장 잘 그려서","mis":"K1-2-u7-X19"},{"t":"새 옷을 입고 와서","mis":"K1-2-u7-X19"}],"explanation":["둘째 줄에 시아가 한 일이 있어요.","그림 솜씨, 새 옷은 글에 없어요.","한 일을 찾아요."],"asset":{"type":"passage","lines":["어제 미술 시간에 내가 물통을 엎었다.","시아가 얼른 걸레를 가져와 같이 닦아 주었다.","창피했던 마음이 스르르 풀렸다."],"title":"루아가 쓴 칭찬하는 글"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#2','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',1,'mc','auto','칭찬하는 글로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":2,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"칭찬하는 글로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 물통을 엎었을 때 같이 닦아 주어서 고마웠어.","correct":true},{"t":"너는 나보다 그림을 못 그려.","mis":"K1-2-u7-X19"},{"t":"넌 그냥 착해.","mis":"K1-2-u7-X19"}],"explanation":["한 일과 마음이 들어 있어요.","견주는 말, 뭉뚱그린 말은 칭찬이 잘 전해지지 않아요.","한 일 + 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#3','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',1,'mc','auto','칭찬하는 글의 세 칸으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":3,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"칭찬하는 글의 세 칸으로 알맞은 것은 어느 것인가요?","options":[{"t":"언제 · 칭찬하고 싶은 일 · 그때 마음","correct":true},{"t":"언제 · 친구의 점수 · 친구의 못하는 점","mis":"K1-2-u7-X19"},{"t":"이름 · 키 · 옷 색깔","mis":"K1-2-u7-X19"}],"explanation":["겪은 일 정리를 그대로 써요.","점수·단점·겉모습은 칭찬거리가 아니에요.","때 · 일 · 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#4','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',1,'mc','auto','칭찬거리가 되는 일은 어느 것인가요?',ARRAY['K1-2-u7-X19']::text[],true,'{"seq":4,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"칭찬거리가 되는 일은 어느 것인가요?","options":[{"t":"혼자 있는 친구에게 같이 놀자고 한 일","correct":true},{"t":"새 가방을 산 것","mis":"K1-2-u7-X19"},{"t":"머리가 긴 것","mis":"K1-2-u7-X19"}],"explanation":["남을 위해 한 일이에요.","가진 물건, 겉모습은 한 일이 아니에요.","그 사람이 한 일."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 칭찬거리가 되는 일은 어느 것인가요?","options":[{"t":"어려운 받아쓰기를 끝까지 다시 연습한 일","correct":true},{"t":"운동화가 반짝이는 것","mis":"K1-2-u7-X19"},{"t":"눈이 큰 것","mis":"K1-2-u7-X19"}],"explanation":["애쓴 일도 칭찬거리예요.","물건, 겉모습은 한 일이 아니에요.","그 사람이 한 일."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#5','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C6',2,'match','auto','칭찬하는 글에서 그 사람이 한 일과 글쓴이의 마음을 선으로 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u7-C6","difficulty":2,"kind":"match","stem":"칭찬하는 글에서 그 사람이 한 일과 글쓴이의 마음을 선으로 이어 보세요.","pairs":[{"l":"엉킨 줄을 같이 풀어 줌","r":"고마웠다"},{"l":"엎은 물을 같이 닦아 줌","r":"창피했던 마음이 풀렸다"},{"l":"운동화 끈을 단단히 매어 줌","r":"든든했다"}],"mis":"K1-2-u7-X13","explanation":["한 일마다 남은 마음이 달라요.","소미 · 루아 · 건우의 글.","글마다 마지막 줄."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#6','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',2,'ox','auto','칭찬하는 글은 같은 반 친구에게만 쓸 수 있어요.',ARRAY['K1-2-u7-X20']::text[],false,'{"seq":6,"concept":"K1-2-u7-C8","difficulty":2,"kind":"ox","stem":"칭찬하는 글은 같은 반 친구에게만 쓸 수 있어요.","answer":"X","reason_options":[{"t":"가족·선생님·이웃에게도 고마운 일이 있으니까","correct":true},{"t":"칭찬은 친구끼리만 하는 말이니까","mis":"K1-2-u7-X20"}],"mis":"K1-2-u7-X20","explanation":["건우는 할아버지께 썼어요.","칭찬 대상은 넓어요.","나를 도와준 사람 누구나."],"asset":{"type":"passage","lines":["어제 저녁 할아버지께서 내 운동화 끈을 단단히 매어 주셨다.","오늘 달리기에서 끈이 한 번도 풀리지 않았다.","할아버지 손이 함께 달려 주는 것 같아 든든했다."],"title":"건우가 쓴 칭찬하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#7','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',2,'mc','auto','더 잘 쓴 칭찬은 어느 것인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":7,"concept":"K1-2-u7-C8","difficulty":2,"kind":"mc","stem":"더 잘 쓴 칭찬은 어느 것인가요?","options":[{"t":"지난 금요일에 떨어진 수저 대신 새 수저를 받아다 주어서 마음이 놓였어.","correct":true},{"t":"재윤이는 좋은 친구야.","mis":"K1-2-u7-X19"},{"t":"재윤이는 최고야.","mis":"K1-2-u7-X19"}],"explanation":["언제·한 일·마음이 다 있어요.","「좋은 친구·최고」는 무슨 일인지 몰라요.","다른 친구도 「맞아!」 할 수 있게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#8','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',2,'mc','auto','루아의 글에서 「언제」 칸에 해당하는 말은 어느 것인가요?',ARRAY['K1-2-u7-X10']::text[],false,'{"seq":8,"concept":"K1-2-u7-C8","difficulty":2,"kind":"mc","stem":"루아의 글에서 「언제」 칸에 해당하는 말은 어느 것인가요?","options":[{"t":"어제 미술 시간에","correct":true},{"t":"시아가 걸레를 가져와","mis":"K1-2-u7-X10"},{"t":"창피했던 마음이 풀렸다","mis":"K1-2-u7-X10"}],"explanation":["첫째 줄의 앞부분이에요.","걸레는 한 일, 풀렸다는 마음이에요.","칸을 나누어 봐요."],"asset":{"type":"passage","lines":["어제 미술 시간에 내가 물통을 엎었다.","시아가 얼른 걸레를 가져와 같이 닦아 주었다.","창피했던 마음이 스르르 풀렸다."],"title":"루아가 쓴 칭찬하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#9','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#10','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',3,'error','auto','칭찬하는 글에 넣을 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#1','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',2,'mc','auto','건우가 칭찬하는 사람은 누구인가요?',ARRAY['K1-2-u7-X20','K1-2-u7-X06']::text[],false,'{"seq":1,"concept":"K1-2-u7-C8","difficulty":2,"kind":"mc","stem":"건우가 칭찬하는 사람은 누구인가요?","options":[{"t":"할아버지","correct":true},{"t":"같은 반 친구","mis":"K1-2-u7-X20"},{"t":"달리기 선생님","mis":"K1-2-u7-X06"}],"explanation":["첫째 줄에 할아버지가 있어요.","친구나 선생님이 아니에요.","칭찬은 누구에게나."],"asset":{"type":"passage","lines":["어제 저녁 할아버지께서 내 운동화 끈을 단단히 매어 주셨다.","오늘 달리기에서 끈이 한 번도 풀리지 않았다.","할아버지 손이 함께 달려 주는 것 같아 든든했다."],"title":"건우가 쓴 칭찬하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#2','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',2,'match','auto','칭찬하고 싶은 사람과 알맞은 칭찬거리를 선으로 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"K1-2-u7-C8","difficulty":2,"kind":"match","stem":"칭찬하고 싶은 사람과 알맞은 칭찬거리를 선으로 이어 보세요.","pairs":[{"l":"동생","r":"어질러진 내 장난감을 같이 정리해 주었어요"},{"l":"이웃 할머니","r":"아침마다 반갑게 인사해 주셨어요"},{"l":"선생님","r":"내 그림을 복도에 걸어 주셨어요"}],"mis":"K1-2-u7-X20","explanation":["가족·이웃·선생님 모두 칭찬할 수 있어요.","사람마다 고마운 일이 달라요.","그 사람이 한 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#3','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',3,'mc','auto','「넌 착해.」를 다른 친구들도 「맞아!」 할 수 있는 칭찬으로 고친 것은 어느 것인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":3,"concept":"K1-2-u7-C8","difficulty":3,"kind":"mc","stem":"「넌 착해.」를 다른 친구들도 「맞아!」 할 수 있는 칭찬으로 고친 것은 어느 것인가요?","options":[{"t":"넌 쉬는 시간마다 칠판을 지워 주어서 우리 반이 깨끗해.","correct":true},{"t":"넌 정말 정말 착해.","mis":"K1-2-u7-X19"},{"t":"넌 나보다 착해.","mis":"K1-2-u7-X19"}],"explanation":["한 일이 들어가야 모두 고개를 끄덕여요.","「정말 정말」, 견주기로는 바뀌지 않아요.","한 일을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#4','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',3,'error','auto','칭찬거리를 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#5','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',3,'ox','auto','칭찬하는 글에 그때 내 마음을 쓰면 칭찬이 더 잘 전해져요.',ARRAY['K1-2-u7-X11']::text[],false,'{"seq":5,"concept":"K1-2-u7-C8","difficulty":3,"kind":"ox","stem":"칭찬하는 글에 그때 내 마음을 쓰면 칭찬이 더 잘 전해져요.","answer":"O","reason_options":[{"t":"받는 사람이 내가 얼마나 고마웠는지 알 수 있으니까","correct":true},{"t":"마음은 칭찬과 상관없으니까","mis":"K1-2-u7-X11"}],"mis":"K1-2-u7-X11","explanation":["마음이 칭찬을 따뜻하게 해요.","세 칸의 마지막이 마음이에요.","그때 마음까지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#6','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',3,'mc','auto','칭찬하는 글을 다 쓴 뒤에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":6,"concept":"K1-2-u7-C8","difficulty":3,"kind":"mc","stem":"칭찬하는 글을 다 쓴 뒤에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"그 사람에게 읽어 주거나 건네요","correct":true},{"t":"칭찬하는 글에 점수를 매겨 줘요","mis":"K1-2-u7-X19"},{"t":"그 사람의 못하는 점도 덧붙여 줘요","mis":"K1-2-u7-X19"}],"explanation":["칭찬은 전해야 힘이 돼요.","점수나 단점은 칭찬을 흐려요.","써서 전하기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#7','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',3,'mc','auto','칭찬과 평가를 바르게 가른 것은 어느 것인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":7,"concept":"K1-2-u7-C8","difficulty":3,"kind":"mc","stem":"칭찬과 평가를 바르게 가른 것은 어느 것인가요?","options":[{"t":"「네가 웃으며 인사해 줘서 하루가 즐거웠어.」는 칭찬이에요.","correct":true},{"t":"「네 글씨는 칠십 점짜리야.」는 칭찬이에요.","mis":"K1-2-u7-X19"},{"t":"「너는 나보다 빨리 달리지 못해.」는 칭찬이에요.","mis":"K1-2-u7-X19"}],"explanation":["한 일 + 마음이 칭찬이에요.","점수 매기기, 견주기는 평가예요.","칭찬 ≠ 평가."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#8','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',4,'sa','auto','다인이가 해 준 일을 찾아 빈칸에 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#9','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',4,'essay','teacher','가족·선생님·이웃 가운데 한 사람을 골라, 세 칸(언제·칭찬하고 싶은 일·그때 마음)으로 칭찬하는 글을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C8","difficulty":4,"kind":"essay","stem":"가족·선생님·이웃 가운데 한 사람을 골라, 세 칸(언제·칭찬하고 싶은 일·그때 마음)으로 칭찬하는 글을 쓰세요.","answer_guide":{"answer":"예: 어제 저녁에 엄마가 내 실내화를 하얗게 빨아 주셨다. 오늘 아침 깨끗한 실내화를 신으니 발까지 산뜻했다. — 친구 아닌 사람에게 세 칸이 다 있으면 맞아요.","scoring_points":["친구가 아닌 사람을 골랐는가","언제·한 일·마음 세 칸이 있는가","견주거나 점수를 매기지 않았는가"]},"explanation":["누구에게나 칭찬할 수 있어요.","세 칸을 다 채워요.","견주지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#10','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',4,'essay','teacher','「넌 그냥 착해.」를 겪은 일이 들어간 칭찬으로 고쳐 쓰고, 왜 그렇게 고쳤는지 한 문장 더 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C8","difficulty":4,"kind":"essay","stem":"「넌 그냥 착해.」를 겪은 일이 들어간 칭찬으로 고쳐 쓰고, 왜 그렇게 고쳤는지 한 문장 더 쓰세요.","answer_guide":{"answer":"예: 오늘 아침 내 가방 지퍼가 열렸을 때 네가 얼른 닫아 주어서 고마웠어. 무엇을 해 주었는지 넣어야 칭찬이 잘 전해지기 때문이에요. — 한 일이 들어간 칭찬과 고친 까닭이 있으면 맞아요.","scoring_points":["그 사람이 한 일이 들어갔는가","그때 마음이 있는가","고친 까닭을 썼는가"]},"explanation":["뭉뚱그린 말 → 한 일.","마음까지 넣어요.","왜 고쳤는지도."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#1','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C1',1,'mc','auto','이 쪽지는 무엇을 알려 주나요?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":1,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"이 쪽지는 무엇을 알려 주나요?","options":[{"t":"줄넘기 줄을 감는 방법","correct":true},{"t":"줄넘기를 잘하는 친구","mis":"K1-2-u7-X01"},{"t":"줄넘기를 산 가게","mis":"K1-2-u7-X01"}],"explanation":["읽으면 줄 감는 법을 알게 돼요.","친구나 가게 이야기는 없어요.","읽고 나서 무엇을 할 수 있나요?"],"asset":{"type":"passage","lines":["줄을 반으로 접어 손잡이 둘을 모아 쥡니다.","줄을 손에 둥글게 감습니다.","줄 끝을 감은 줄 사이에 끼워 둡니다.","그러면 다음에 꺼낼 때 엉키지 않습니다."],"title":"「줄넘기 줄을 감는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#2','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C2',1,'mc','auto','이 글은 무엇을 설명하나요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":2,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"이 글은 무엇을 설명하나요?","options":[{"t":"해바라기","correct":true},{"t":"새","mis":"K1-2-u7-X04"},{"t":"기름","mis":"K1-2-u7-X04"}],"explanation":["모든 줄에 해바라기가 나와요.","새·기름은 한 줄에만 나와요.","모든 줄에 나오는 것."],"asset":{"type":"passage","lines":["해바라기는 키가 큰 여름꽃입니다.","해바라기는 노랗고 커다란 꽃을 피웁니다.","해바라기 꽃 가운데에는 씨앗이 촘촘히 모여 있습니다.","해바라기 씨앗은 새들의 먹이가 되고, 사람들은 그 씨앗으로 기름을 짭니다."],"title":"「해바라기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#3','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C3',1,'mc','auto','이 글 전체가 설명하는 것은 무엇인가요?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"이 글 전체가 설명하는 것은 무엇인가요?","options":[{"t":"개미","correct":true},{"t":"일꾼","mis":"K1-2-u7-X03"},{"t":"먹이","mis":"K1-2-u7-X04"}],"explanation":["세 문단 모두 개미 이야기예요.","일꾼은 제목, 먹이는 한 문단에만 있어요.","문단을 합쳐요."],"asset":{"type":"passage","lines":["개미는 땅속에 길을 내고 여러 개의 방을 만듭니다.","개미는 자기 몸보다 큰 먹이도 여럿이 함께 들어 옮깁니다.","개미는 더듬이를 맞대어 서로 소식을 전합니다."],"title":"「작아도 힘센 일꾼」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#4','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C4',1,'mc','auto','글을 읽고 새롭게 안 점으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X07']::text[],false,'{"seq":4,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 새롭게 안 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"해바라기 씨앗은 새들의 먹이가 된다는 것","correct":true},{"t":"해바라기는 겨울에 피는 꽃이라는 것","mis":"K1-2-u7-X07"},{"t":"해바라기 씨앗은 파란색이라는 것","mis":"K1-2-u7-X07"}],"explanation":["넷째 줄에 있어요.","겨울꽃, 파란 씨앗은 글에 없어요.","글 어디에 있나요?"],"asset":{"type":"passage","lines":["해바라기는 키가 큰 여름꽃입니다.","해바라기는 노랗고 커다란 꽃을 피웁니다.","해바라기 꽃 가운데에는 씨앗이 촘촘히 모여 있습니다.","해바라기 씨앗은 새들의 먹이가 되고, 사람들은 그 씨앗으로 기름을 짭니다."],"title":"「해바라기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#5','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C5',1,'mc','auto','재윤이에게 있었던 일은 언제 있었나요?',ARRAY['K1-2-u7-X06','K1-2-u7-X08']::text[],false,'{"seq":5,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"재윤이에게 있었던 일은 언제 있었나요?","options":[{"t":"지난 일요일","correct":true},{"t":"오늘 아침","mis":"K1-2-u7-X06"},{"t":"다음 주","mis":"K1-2-u7-X08"}],"explanation":["첫째 줄에 있어요.","다음 주는 아직이에요.","언제 칸."],"asset":{"type":"passage","lines":["지난 일요일, 공원에서 두발자전거를 탔어요.","아빠가 뒤에서 안장을 잡아 주셔서 든든했어요.","한참 가다 돌아보니 아빠가 저 멀리 서 계셨어요.","깜짝 놀랐지만 넘어지지 않고 끝까지 갔어요.","혼자 해냈다는 생각에 가슴이 두근두근 벅찼어요."],"title":"재윤이가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#6','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C6',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u7-X12']::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"든든했다","correct":true},{"t":"돌아보았다","mis":"K1-2-u7-X12"},{"t":"공원에 갔다","mis":"K1-2-u7-X12"}],"explanation":["「든든했다」는 마음이 느낀 것이에요.","돌아보기, 가기는 몸이 한 일이에요.","몸? 마음?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#7','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C7',1,'mc','auto','그 자리에 있었던 것처럼 그려지는 문장은 어느 것인가요?',ARRAY['K1-2-u7-X15']::text[],false,'{"seq":7,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"그 자리에 있었던 것처럼 그려지는 문장은 어느 것인가요?","options":[{"t":"물안경을 쓰고 물속에 들어가자 바닥의 조약돌이 반짝였다.","correct":true},{"t":"수영장에 갔다 왔다.","mis":"K1-2-u7-X15"},{"t":"수영을 했다.","mis":"K1-2-u7-X15"}],"explanation":["본 것이 눈에 그려져요.","「갔다 왔다·했다」는 장면이 흐려요.","본 것·한 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#8','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C8',1,'mc','auto','소미가 다인이를 칭찬하는 까닭은 무엇인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":8,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"소미가 다인이를 칭찬하는 까닭은 무엇인가요?","options":[{"t":"엉킨 줄넘기 줄을 같이 풀어 주어서","correct":true},{"t":"줄넘기를 가장 잘해서","mis":"K1-2-u7-X19"},{"t":"키가 커서","mis":"K1-2-u7-X19"}],"explanation":["다인이가 한 일이에요.","잘하는 것, 키는 글에 없어요.","한 일."],"asset":{"type":"passage","lines":["오늘 체육 시간에 내 줄넘기 줄이 엉켜 버렸다.","짝 다인이가 엉킨 줄을 같이 풀어 주었다.","덕분에 끝까지 넘을 수 있어서 고마웠다."],"title":"소미가 쓴 칭찬하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#9','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C2',2,'mc','auto','줄마다 되풀이 나오는 낱말은 어느 것인가요?',ARRAY['K1-2-u7-X05']::text[],false,'{"seq":9,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"줄마다 되풀이 나오는 낱말은 어느 것인가요?","options":[{"t":"해바라기","correct":true},{"t":"씨앗","mis":"K1-2-u7-X05"},{"t":"기름","mis":"K1-2-u7-X05"}],"explanation":["네 줄 모두 「해바라기」.","씨앗은 두 줄, 기름은 한 줄.","동그라미를 쳐 봐요."],"asset":{"type":"passage","lines":["해바라기는 키가 큰 여름꽃입니다.","해바라기는 노랗고 커다란 꽃을 피웁니다.","해바라기 꽃 가운데에는 씨앗이 촘촘히 모여 있습니다.","해바라기 씨앗은 새들의 먹이가 되고, 사람들은 그 씨앗으로 기름을 짭니다."],"title":"「해바라기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#10','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C3',2,'match','auto','문단과 그 문단이 알려 주는 것을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C3","difficulty":2,"kind":"match","stem":"문단과 그 문단이 알려 주는 것을 선으로 이어 보세요.","pairs":[{"l":"첫째 문단","r":"땅속에 길과 방을 만들어요"},{"l":"둘째 문단","r":"먹이를 함께 들어 옮겨요"},{"l":"셋째 문단","r":"더듬이로 소식을 전해요"}],"mis":"K1-2-u7-X06","explanation":["문단마다 개미가 하는 일이 달라요.","합치면 개미 이야기.","문단을 짚어요."],"asset":{"type":"passage","lines":["개미는 땅속에 길을 내고 여러 개의 방을 만듭니다.","개미는 자기 몸보다 큰 먹이도 여럿이 함께 들어 옮깁니다.","개미는 더듬이를 맞대어 서로 소식을 전합니다."],"title":"「작아도 힘센 일꾼」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#11','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C6',2,'match','auto','장면과 그때 재윤이의 마음을 선으로 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K1-2-u7-C6","difficulty":2,"kind":"match","stem":"장면과 그때 재윤이의 마음을 선으로 이어 보세요.","pairs":[{"l":"아빠가 안장을 잡아 줄 때","r":"든든했어요"},{"l":"아빠가 멀리 서 계신 것을 봤을 때","r":"깜짝 놀랐어요"},{"l":"끝까지 혼자 갔을 때","r":"가슴이 벅찼어요"}],"mis":"K1-2-u7-X13","explanation":["장면이 바뀌면 마음도 바뀌어요.","든든 → 놀람 → 벅참.","줄을 짚어요."],"asset":{"type":"passage","lines":["지난 일요일, 공원에서 두발자전거를 탔어요.","아빠가 뒤에서 안장을 잡아 주셔서 든든했어요.","한참 가다 돌아보니 아빠가 저 멀리 서 계셨어요.","깜짝 놀랐지만 넘어지지 않고 끝까지 갔어요.","혼자 해냈다는 생각에 가슴이 두근두근 벅찼어요."],"title":"재윤이가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#12','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C1',2,'ox','auto','「할머니께 보내는 편지」는 설명하는 글이에요.',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":12,"concept":"K1-2-u7-C1","difficulty":2,"kind":"ox","stem":"「할머니께 보내는 편지」는 설명하는 글이에요.","answer":"X","reason_options":[{"t":"무엇을 어떻게 하는지 알려 주는 글이 아니니까","correct":true},{"t":"글자가 많으면 설명하는 글이니까","mis":"K1-2-u7-X01"}],"mis":"K1-2-u7-X01","explanation":["편지는 마음을 전하는 글이에요.","설명하는 글은 방법·무엇인지를 알려 줘요.","읽고 무엇을 알게 되나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#13','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C5',2,'ox','auto','겪은 일은 생일이나 여행처럼 특별한 날에 있었던 일만 쓸 수 있어요.',ARRAY['K1-2-u7-X09']::text[],false,'{"seq":13,"concept":"K1-2-u7-C5","difficulty":2,"kind":"ox","stem":"겪은 일은 생일이나 여행처럼 특별한 날에 있었던 일만 쓸 수 있어요.","answer":"X","reason_options":[{"t":"날마다 있는 일도 마음이 움직였다면 글감이 되니까","correct":true},{"t":"특별해야 읽는 사람이 좋아하니까","mis":"K1-2-u7-X09"}],"mis":"K1-2-u7-X09","explanation":["평범한 일도 글감이에요.","달걀 깨기, 이 빠지기처럼요.","마음이 움직인 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#14','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C8',2,'mc','auto','칭찬하는 글로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":14,"concept":"K1-2-u7-C8","difficulty":2,"kind":"mc","stem":"칭찬하는 글로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 넘어졌을 때 손을 잡아 일으켜 주어서 고마웠어.","correct":true},{"t":"너는 나보다 달리기를 못해.","mis":"K1-2-u7-X19"},{"t":"넌 그냥 좋은 애야.","mis":"K1-2-u7-X19"}],"explanation":["한 일과 마음이 있어요.","견주기, 뭉뚱그린 말은 칭찬이 잘 안 전해져요.","한 일 + 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#15','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C7',2,'mc','auto','친구 글을 나누어 읽을 때 먼저 할 일은 무엇인가요?',ARRAY['K1-2-u7-X18']::text[],false,'{"seq":15,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"친구 글을 나누어 읽을 때 먼저 할 일은 무엇인가요?","options":[{"t":"좋은 표현을 찾아 칭찬해요","correct":true},{"t":"틀린 글자를 세어요","mis":"K1-2-u7-X18"},{"t":"누구 글이 긴지 견주어요","mis":"K1-2-u7-X18"}],"explanation":["좋은 점부터.","틀린 글자·길이 견주기가 목적이 아니에요.","일과 마음이 드러났나?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#16','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C6',2,'mc','auto','이 표정에 어울리지 않는 말은 어느 것인가요?',ARRAY['K1-2-u7-X13']::text[],false,'{"seq":16,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"이 표정에 어울리지 않는 말은 어느 것인가요?","options":[{"t":"겁나다","correct":true},{"t":"반갑다","mis":"K1-2-u7-X13"},{"t":"흐뭇하다","mis":"K1-2-u7-X13"}],"explanation":["웃는 얼굴에 「겁나다」는 어울리지 않아요.","반갑다·흐뭇하다는 어울려요.","하나만 다른 것."],"asset":{"type":"scene","icon":"😊","text":"활짝 웃는 얼굴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
