INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#18','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C4',3,'error','auto','「작아도 힘센 일꾼」을 읽고 새롭게 안 점을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#19','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C5',3,'error','auto','재윤이가 겪은 일을 네 칸으로 정리했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#20','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C7',3,'mc','auto','루아의 글을 고쳐 쓸 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K1-2-u7-X14','K1-2-u7-X11']::text[],false,'{"seq":20,"concept":"K1-2-u7-C7","difficulty":3,"kind":"mc","stem":"루아의 글을 고쳐 쓸 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"가장 기억에 남는 일 하나를 골라 자세히 써요","correct":true},{"t":"한 일을 더 많이 늘어놓아요","mis":"K1-2-u7-X14"},{"t":"끝에 「재미있었다」를 붙여요","mis":"K1-2-u7-X11"}],"explanation":["하나를 골라 자세히.","늘어놓거나 한마디 붙이면 그대로예요.","하나를 자세히."],"asset":{"type":"passage","lines":["아침에 일어났다. 밥을 먹었다.","학교에 갔다. 공부를 했다.","집에 왔다. 숙제를 했다.","저녁을 먹고 잠을 잤다."],"title":"루아가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#21','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C8',3,'error','auto','칭찬거리를 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#22','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C2',3,'mc','auto','이 글에 「새」가 나온 까닭은 무엇인가요?',ARRAY['K1-2-u7-X04','K1-2-u7-X03']::text[],false,'{"seq":22,"concept":"K1-2-u7-C2","difficulty":3,"kind":"mc","stem":"이 글에 「새」가 나온 까닭은 무엇인가요?","options":[{"t":"해바라기 씨앗이 주는 도움을 보여 주려고","correct":true},{"t":"새를 설명하려고","mis":"K1-2-u7-X04"},{"t":"새가 제목이라서","mis":"K1-2-u7-X03"}],"explanation":["씨앗이 새의 먹이가 된다는 것을 알려 줘요.","새는 한 줄뿐이고 제목도 아니에요.","글 전체는 해바라기."],"asset":{"type":"passage","lines":["해바라기는 키가 큰 여름꽃입니다.","해바라기는 노랗고 커다란 꽃을 피웁니다.","해바라기 꽃 가운데에는 씨앗이 촘촘히 모여 있습니다.","해바라기 씨앗은 새들의 먹이가 되고, 사람들은 그 씨앗으로 기름을 짭니다."],"title":"「해바라기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#23','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C2',4,'sa','auto','제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇을 설명하는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u7-C2","difficulty":4,"kind":"sa","stem":"제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇을 설명하는지 쓰세요.","answer":["연필깎이","연필 깎이"],"explanation":["세 줄 모두 「연필깎이」.","연필은 깎이는 것이에요.","되풀이 낱말."],"asset":{"type":"passage","lines":["연필이 뭉툭해지면 연필깎이에 넣고 손잡이를 돌립니다.","연필깎이 안의 칼날이 연필 끝을 뾰족하게 깎습니다.","연필깎이에 부스러기가 차면 서랍을 빼서 비웁니다."],"title":"제목을 가린 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#24','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C7',4,'essay','teacher','무언가를 처음 해 본 일을 하나 골라, 본 것·한 일·그때 마음이 들어가게 일이 일어난 차례로 세 문장 넘게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u7-C7","difficulty":4,"kind":"essay","stem":"무언가를 처음 해 본 일을 하나 골라, 본 것·한 일·그때 마음이 들어가게 일이 일어난 차례로 세 문장 넘게 쓰세요.","answer_guide":{"answer":"예: 지난 토요일 처음으로 혼자 머리를 감았다. 샴푸 거품이 눈에 들어갈까 봐 눈을 꼭 감고 손으로 머리를 비볐다. 다 헹구고 거울을 보니 머리카락이 반짝여서 뿌듯했다. — 한 가지 일이 차례대로, 장면과 까닭 있는 마음이 있으면 맞아요.","scoring_points":["한 가지 일을 골라 자세히 썼는가","본 것이나 한 일로 장면이 그려지는가","마음에 까닭이 있는가"]},"explanation":["하나를 자세히.","차례대로.","마음은 까닭과 함께."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#25','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C8',4,'essay','teacher','가족 가운데 한 사람을 골라, 세 칸(언제·칭찬하고 싶은 일·그때 마음)으로 칭찬하는 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u7-C8","difficulty":4,"kind":"essay","stem":"가족 가운데 한 사람을 골라, 세 칸(언제·칭찬하고 싶은 일·그때 마음)으로 칭찬하는 글을 쓰세요.","answer_guide":{"answer":"예: 어제 저녁에 누나가 내 숙제를 옆에서 같이 봐 주었다. 어려운 문제를 풀고 나니 머리가 시원했다. — 언제·한 일·마음이 있고 견주지 않았으면 맞아요.","scoring_points":["언제가 있는가","그 사람이 한 일이 있는가","그때 마음이 있고 견주거나 점수를 매기지 않았는가"]},"explanation":["세 칸.","한 일을 꼭.","견주지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#1','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C1',1,'mc','auto','이 쪽지는 무엇을 알려 주나요?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":1,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"이 쪽지는 무엇을 알려 주나요?","options":[{"t":"실내화를 빠는 방법","correct":true},{"t":"실내화가 예쁜 친구","mis":"K1-2-u7-X01"},{"t":"실내화를 산 가게","mis":"K1-2-u7-X01"}],"explanation":["읽으면 실내화 빠는 법을 알게 돼요.","친구나 가게 이야기는 없어요.","읽고 나서 무엇을 할 수 있나요?"],"asset":{"type":"passage","lines":["실내화를 물에 푹 적십니다.","솔에 비누를 묻혀 바닥과 앞코를 문지릅니다.","맑은 물로 비누 거품을 헹굽니다.","햇볕이 드는 곳에 세워 말립니다."],"title":"「실내화를 빠는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#2','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C2',1,'mc','auto','이 글은 무엇을 설명하나요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":2,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"이 글은 무엇을 설명하나요?","options":[{"t":"거북","correct":true},{"t":"모래","mis":"K1-2-u7-X04"},{"t":"알","mis":"K1-2-u7-X04"}],"explanation":["모든 줄에 거북이 나와요.","모래·알은 한 줄에만 나와요.","모든 줄에 나오는 것."],"asset":{"type":"passage","lines":["거북은 단단한 등딱지를 가진 동물입니다.","거북은 위험하면 머리와 다리를 등딱지 속에 넣습니다.","바다거북은 바닷가 모래에 구멍을 파고 알을 낳습니다.","거북은 아주 오래 사는 동물입니다."],"title":"「거북」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#3','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C3',1,'mc','auto','이 글 전체가 설명하는 것은 무엇인가요?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"이 글 전체가 설명하는 것은 무엇인가요?","options":[{"t":"동물들이 사는 집","correct":true},{"t":"잠","mis":"K1-2-u7-X03"},{"t":"두더지","mis":"K1-2-u7-X04"}],"explanation":["세 문단을 합치면 동물들의 집이에요.","잠은 제목, 두더지는 한 문단에만 있어요.","문단을 합쳐요."],"asset":{"type":"passage","lines":["까치는 나뭇가지를 모아 높은 나무 위에 집을 짓습니다.","두더지는 땅속에 굴을 길게 파고 삽니다.","비버는 나무를 갉아 물 위에 집을 짓습니다."],"title":"「어디에서 잠을 잘까?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#4','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C4',1,'mc','auto','글을 읽고 새롭게 안 점으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X07']::text[],false,'{"seq":4,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 새롭게 안 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"바다거북은 모래에 구멍을 파고 알을 낳는다는 것","correct":true},{"t":"거북은 나무 위에서 잠을 잔다는 것","mis":"K1-2-u7-X07"},{"t":"거북은 금방 자라 일찍 죽는다는 것","mis":"K1-2-u7-X07"}],"explanation":["셋째 줄에 있어요.","나무 위, 일찍 죽는다는 말은 없어요.","글 어디에 있나요?"],"asset":{"type":"passage","lines":["거북은 단단한 등딱지를 가진 동물입니다.","거북은 위험하면 머리와 다리를 등딱지 속에 넣습니다.","바다거북은 바닷가 모래에 구멍을 파고 알을 낳습니다.","거북은 아주 오래 사는 동물입니다."],"title":"「거북」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#5','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C5',1,'mc','auto','예린이에게 있었던 일은 어디에서 있었나요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":5,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"예린이에게 있었던 일은 어디에서 있었나요?","options":[{"t":"학교 현관","correct":true},{"t":"할머니 집","mis":"K1-2-u7-X06"},{"t":"버스 정류장","mis":"K1-2-u7-X06"}],"explanation":["첫째 줄에 있어요.","할머니 집·정류장은 글에 없어요.","어디에서 칸."],"asset":{"type":"passage","lines":["어제 학교가 끝나고 현관에 서 있었어요.","비가 쏟아지는데 우산이 없어서 막막했어요.","친구들이 하나둘 가 버리자 서운해서 눈물이 날 것 같았어요.","그때 할머니가 노란 우산을 들고 오셨어요.","할머니 손을 꼭 잡으니 마음이 따뜻해졌어요."],"title":"예린이가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#6','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C6',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u7-X12']::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"막막했다","correct":true},{"t":"현관에 섰다","mis":"K1-2-u7-X12"},{"t":"손을 잡았다","mis":"K1-2-u7-X12"}],"explanation":["「막막했다」는 마음이 느낀 것이에요.","서기, 잡기는 몸이 한 일이에요.","몸? 마음?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#7','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C7',1,'mc','auto','그 자리에 있었던 것처럼 그려지는 문장은 어느 것인가요?',ARRAY['K1-2-u7-X15']::text[],false,'{"seq":7,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"그 자리에 있었던 것처럼 그려지는 문장은 어느 것인가요?","options":[{"t":"실을 당기자 연이 바람을 타고 하늘 높이 솟았다.","correct":true},{"t":"연을 날렸다.","mis":"K1-2-u7-X15"},{"t":"밖에 나갔다 왔다.","mis":"K1-2-u7-X15"}],"explanation":["한 일과 본 것이 그려져요.","「날렸다·나갔다 왔다」는 장면이 흐려요.","본 것·한 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#8','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C8',1,'mc','auto','루아가 시아를 칭찬하는 까닭은 무엇인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":8,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"루아가 시아를 칭찬하는 까닭은 무엇인가요?","options":[{"t":"엎은 물을 같이 닦아 주어서","correct":true},{"t":"그림을 잘 그려서","mis":"K1-2-u7-X19"},{"t":"새 옷을 입어서","mis":"K1-2-u7-X19"}],"explanation":["시아가 한 일이에요.","그림 솜씨, 옷은 글에 없어요.","한 일."],"asset":{"type":"passage","lines":["어제 미술 시간에 내가 물통을 엎었다.","시아가 얼른 걸레를 가져와 같이 닦아 주었다.","창피했던 마음이 스르르 풀렸다."],"title":"루아가 쓴 칭찬하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#9','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C2',2,'mc','auto','줄마다 되풀이 나오는 낱말은 어느 것인가요?',ARRAY['K1-2-u7-X05']::text[],false,'{"seq":9,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"줄마다 되풀이 나오는 낱말은 어느 것인가요?","options":[{"t":"거북","correct":true},{"t":"알","mis":"K1-2-u7-X05"},{"t":"모래","mis":"K1-2-u7-X05"}],"explanation":["네 줄 모두 「거북」(바다거북 포함).","알·모래는 한 줄.","동그라미를 쳐 봐요."],"asset":{"type":"passage","lines":["거북은 단단한 등딱지를 가진 동물입니다.","거북은 위험하면 머리와 다리를 등딱지 속에 넣습니다.","바다거북은 바닷가 모래에 구멍을 파고 알을 낳습니다.","거북은 아주 오래 사는 동물입니다."],"title":"「거북」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#10','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C3',2,'match','auto','동물과 그 동물이 사는 집을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C3","difficulty":2,"kind":"match","stem":"동물과 그 동물이 사는 집을 선으로 이어 보세요.","pairs":[{"l":"까치","r":"높은 나무 위 나뭇가지 집"},{"l":"두더지","r":"땅속에 길게 판 굴"},{"l":"비버","r":"물 위에 지은 나무 집"}],"mis":"K1-2-u7-X06","explanation":["동물마다 집이 달라요.","합치면 동물들의 집 이야기.","문단을 짚어요."],"asset":{"type":"passage","lines":["까치는 나뭇가지를 모아 높은 나무 위에 집을 짓습니다.","두더지는 땅속에 굴을 길게 파고 삽니다.","비버는 나무를 갉아 물 위에 집을 짓습니다."],"title":"「어디에서 잠을 잘까?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#11','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C6',2,'match','auto','장면과 그때 예린이의 마음을 선으로 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K1-2-u7-C6","difficulty":2,"kind":"match","stem":"장면과 그때 예린이의 마음을 선으로 이어 보세요.","pairs":[{"l":"우산이 없는 것을 알았을 때","r":"막막했어요"},{"l":"친구들이 가 버렸을 때","r":"서운했어요"},{"l":"할머니 손을 잡았을 때","r":"마음이 따뜻해졌어요"}],"mis":"K1-2-u7-X13","explanation":["장면이 바뀌면 마음도 바뀌어요.","막막 → 서운 → 따뜻.","줄을 짚어요."],"asset":{"type":"passage","lines":["어제 학교가 끝나고 현관에 서 있었어요.","비가 쏟아지는데 우산이 없어서 막막했어요.","친구들이 하나둘 가 버리자 서운해서 눈물이 날 것 같았어요.","그때 할머니가 노란 우산을 들고 오셨어요.","할머니 손을 꼭 잡으니 마음이 따뜻해졌어요."],"title":"예린이가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#12','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C1',2,'ox','auto','「종이비행기를 접는 방법」은 설명하는 글이에요.',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":12,"concept":"K1-2-u7-C1","difficulty":2,"kind":"ox","stem":"「종이비행기를 접는 방법」은 설명하는 글이에요.","answer":"O","reason_options":[{"t":"읽으면 종이비행기를 어떻게 접는지 알게 되니까","correct":true},{"t":"놀이에 대한 글은 모두 이야기니까","mis":"K1-2-u7-X01"}],"mis":"K1-2-u7-X01","explanation":["접는 방법을 알려 줘요.","놀이도 방법을 설명할 수 있어요.","「~하는 방법」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#13','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C5',2,'ox','auto','비 오는 날 우산이 없어 기다린 일도 겪은 일 글감이 돼요.',ARRAY['K1-2-u7-X09']::text[],false,'{"seq":13,"concept":"K1-2-u7-C5","difficulty":2,"kind":"ox","stem":"비 오는 날 우산이 없어 기다린 일도 겪은 일 글감이 돼요.","answer":"O","reason_options":[{"t":"마음이 움직인 일이면 어떤 일이든 글감이 되니까","correct":true},{"t":"비 오는 날은 누구나 겪어서 쓸 게 없으니까","mis":"K1-2-u7-X09"}],"mis":"K1-2-u7-X09","explanation":["작은 일도 글감이에요.","그때 마음이 있으면 돼요.","마음이 움직인 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#14','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C8',2,'mc','auto','칭찬하는 글로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":14,"concept":"K1-2-u7-C8","difficulty":2,"kind":"mc","stem":"칭찬하는 글로 알맞은 것은 어느 것인가요?","options":[{"t":"무거운 책을 함께 들어 주어서 팔이 덜 아팠어.","correct":true},{"t":"너는 우리 반에서 두 번째로 착해.","mis":"K1-2-u7-X19"},{"t":"넌 최고야.","mis":"K1-2-u7-X19"}],"explanation":["한 일과 마음이 있어요.","순서 매기기, 뭉뚱그린 말은 칭찬이 잘 안 전해져요.","한 일 + 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#15','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C7',2,'mc','auto','친구 글을 나누어 읽을 때 살펴볼 것은 어느 것인가요?',ARRAY['K1-2-u7-X18']::text[],false,'{"seq":15,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"친구 글을 나누어 읽을 때 살펴볼 것은 어느 것인가요?","options":[{"t":"그때 마음이 드러났는지","correct":true},{"t":"글씨가 누가 더 큰지","mis":"K1-2-u7-X18"},{"t":"쪽수가 몇 쪽인지","mis":"K1-2-u7-X18"}],"explanation":["마음이 드러났는지 봐요.","글씨 크기·쪽수는 상관없어요.","일과 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#16','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C6',2,'mc','auto','이 표정에 어울리지 않는 말은 어느 것인가요?',ARRAY['K1-2-u7-X13']::text[],false,'{"seq":16,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"이 표정에 어울리지 않는 말은 어느 것인가요?","options":[{"t":"졸리다","correct":true},{"t":"깜짝 놀라다","mis":"K1-2-u7-X13"},{"t":"어리둥절하다","mis":"K1-2-u7-X13"}],"explanation":["눈이 동그래진 얼굴에 「졸리다」는 어울리지 않아요.","깜짝 놀라다·어리둥절하다는 어울려요.","하나만 다른 것."],"asset":{"type":"scene","icon":"😮","text":"눈이 동그래진 얼굴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#17','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C3',3,'error','auto','「어디에서 잠을 잘까?」가 무엇을 설명하는지 친구들이 답했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#18','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C4',3,'error','auto','「어디에서 잠을 잘까?」를 읽고 새롭게 안 점을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#19','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C5',3,'error','auto','예린이가 겪은 일을 네 칸으로 정리했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#20','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C7',3,'mc','auto','일이 일어난 차례로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K1-2-u7-X17']::text[],false,'{"seq":20,"concept":"K1-2-u7-C7","difficulty":3,"kind":"mc","stem":"일이 일어난 차례로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"② → ④ → ① → ③","correct":true},{"t":"① → ② → ④ → ③","mis":"K1-2-u7-X17"},{"t":"② → ① → ④ → ③","mis":"K1-2-u7-X17"}],"explanation":["도착 → 쌓기 → 무너짐 → 다짐.","쌓기 전에 무너질 수 없어요.","처음·가운데·끝."],"asset":{"type":"passage","lines":["① 모래성이 파도에 스르르 무너졌다.","② 아침에 바닷가에 도착했다.","③ 아쉬웠지만 다음에는 더 크게 쌓기로 했다.","④ 모래를 모아 성을 쌓았다."],"title":"차례가 섞인 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#21','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C8',3,'error','auto','칭찬거리를 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#22','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C2',3,'mc','auto','이 글에 「모래」가 나온 까닭은 무엇인가요?',ARRAY['K1-2-u7-X04','K1-2-u7-X03']::text[],false,'{"seq":22,"concept":"K1-2-u7-C2","difficulty":3,"kind":"mc","stem":"이 글에 「모래」가 나온 까닭은 무엇인가요?","options":[{"t":"바다거북이 알을 낳는 곳을 보여 주려고","correct":true},{"t":"모래를 설명하려고","mis":"K1-2-u7-X04"},{"t":"모래가 제목이라서","mis":"K1-2-u7-X03"}],"explanation":["모래에 알을 낳는다는 것을 알려 줘요.","모래는 한 줄뿐이고 제목도 아니에요.","글 전체는 거북."],"asset":{"type":"passage","lines":["거북은 단단한 등딱지를 가진 동물입니다.","거북은 위험하면 머리와 다리를 등딱지 속에 넣습니다.","바다거북은 바닷가 모래에 구멍을 파고 알을 낳습니다.","거북은 아주 오래 사는 동물입니다."],"title":"「거북」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#23','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C2',4,'sa','auto','제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇을 설명하는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u7-C2","difficulty":4,"kind":"sa","stem":"제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇을 설명하는지 쓰세요.","answer":["무지개"],"explanation":["세 줄 모두 「무지개」.","비와 해는 실마리일 뿐이에요.","되풀이 낱말."],"asset":{"type":"passage","lines":["비가 그친 뒤 해가 나면 하늘에 무지개가 뜹니다.","무지개는 여러 가지 색이 줄지어 있습니다.","무지개는 해를 등지고 서야 볼 수 있습니다."],"title":"제목을 가린 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#24','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C7',4,'essay','teacher','비나 눈이 온 날 겪은 일을 하나 골라, 본 것·들은 것·그때 마음이 들어가게 일이 일어난 차례로 세 문장 넘게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u7-C7","difficulty":4,"kind":"essay","stem":"비나 눈이 온 날 겪은 일을 하나 골라, 본 것·들은 것·그때 마음이 들어가게 일이 일어난 차례로 세 문장 넘게 쓰세요.","answer_guide":{"answer":"예: 어제 아침 창문을 여니 마당이 하얗게 덮여 있었다. 장화를 신고 나가자 눈이 뽀드득뽀드득 소리를 냈다. 내 발자국이 길게 이어져서 마음이 설렜다. — 한 가지 일이 차례대로, 장면과 까닭 있는 마음이 있으면 맞아요.","scoring_points":["한 가지 일을 골라 자세히 썼는가","본 것이나 들은 것으로 장면이 그려지는가","마음에 까닭이 있는가"]},"explanation":["하나를 자세히.","차례대로.","마음은 까닭과 함께."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#25','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C8',4,'essay','teacher','선생님께 칭찬하는 글을 세 칸(언제·칭찬하고 싶은 일·그때 마음)으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u7-C8","difficulty":4,"kind":"essay","stem":"선생님께 칭찬하는 글을 세 칸(언제·칭찬하고 싶은 일·그때 마음)으로 쓰세요.","answer_guide":{"answer":"예: 오늘 아침 선생님께서 내 그림을 칠판 옆에 붙여 주셨다. 친구들이 보러 와서 어깨가 으쓱했다. — 언제·한 일·마음이 있고 견주지 않았으면 맞아요.","scoring_points":["언제가 있는가","선생님이 하신 일이 있는가","그때 마음이 있고 견주거나 점수를 매기지 않았는가"]},"explanation":["세 칸.","한 일을 꼭.","견주지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#1','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C1',1,'mc','auto','이 쪽지는 무엇을 알려 주나요?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":1,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"이 쪽지는 무엇을 알려 주나요?","options":[{"t":"다 마신 우유갑을 정리하는 방법","correct":true},{"t":"우유를 많이 마신 친구","mis":"K1-2-u7-X01"},{"t":"우유를 만드는 곳","mis":"K1-2-u7-X01"}],"explanation":["읽으면 우유갑 정리하는 법을 알게 돼요.","친구나 만드는 곳 이야기는 없어요.","읽고 나서 무엇을 할 수 있나요?"],"asset":{"type":"passage","lines":["다 마신 우유갑에 물을 조금 넣어 헹굽니다.","우유갑의 입구를 활짝 펼칩니다.","손바닥으로 눌러 납작하게 만듭니다.","우유갑을 모으는 상자에 넣습니다."],"title":"「다 마신 우유갑을 정리하는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#2','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C2',1,'mc','auto','이 글은 무엇을 설명하나요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":2,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"이 글은 무엇을 설명하나요?","options":[{"t":"돋보기","correct":true},{"t":"개미","mis":"K1-2-u7-X04"},{"t":"할머니","mis":"K1-2-u7-X04"}],"explanation":["모든 줄에 돋보기가 나와요.","개미·할머니는 한 줄에만 나와요.","모든 줄에 나오는 것."],"asset":{"type":"passage","lines":["돋보기는 작은 것을 크게 보여 주는 도구입니다.","돋보기로 보면 개미 다리에 난 털도 보입니다.","할머니는 돋보기를 쓰고 작은 글씨를 읽으십니다.","과학 시간에는 돋보기로 나뭇잎의 잎맥을 관찰합니다."],"title":"「돋보기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#3','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C3',1,'mc','auto','이 글 전체가 설명하는 것은 무엇인가요?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"이 글 전체가 설명하는 것은 무엇인가요?","options":[{"t":"씨앗이 멀리 퍼지는 방법","correct":true},{"t":"먼 곳으로 떠나는 여행","mis":"K1-2-u7-X03"},{"t":"단풍나무","mis":"K1-2-u7-X04"}],"explanation":["세 문단을 합치면 씨앗이 퍼지는 방법이에요.","여행은 제목에서 떠올린 것, 단풍나무는 한 문단이에요.","문단을 합쳐요."],"asset":{"type":"passage","lines":["단풍나무 씨앗은 날개가 있어 바람을 타고 빙글빙글 날아갑니다.","봉숭아 씨앗은 꼬투리가 톡 터지면서 멀리 튀어 나갑니다.","야자 열매는 물에 둥둥 떠서 먼 바닷가까지 갑니다."],"title":"「멀리멀리 떠나요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#4','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C4',1,'mc','auto','글을 읽고 새롭게 안 점으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X07']::text[],false,'{"seq":4,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 새롭게 안 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"돋보기로 보면 개미 다리의 털도 보인다는 것","correct":true},{"t":"돋보기로 멀리 있는 산을 본다는 것","mis":"K1-2-u7-X07"},{"t":"돋보기는 소리를 크게 해 준다는 것","mis":"K1-2-u7-X07"}],"explanation":["둘째 줄에 있어요.","먼 산, 소리 이야기는 없어요.","글 어디에 있나요?"],"asset":{"type":"passage","lines":["돋보기는 작은 것을 크게 보여 주는 도구입니다.","돋보기로 보면 개미 다리에 난 털도 보입니다.","할머니는 돋보기를 쓰고 작은 글씨를 읽으십니다.","과학 시간에는 돋보기로 나뭇잎의 잎맥을 관찰합니다."],"title":"「돋보기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#5','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C5',1,'mc','auto','건우에게 있었던 일은 언제 있었나요?',ARRAY['K1-2-u7-X06','K1-2-u7-X08']::text[],false,'{"seq":5,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"건우에게 있었던 일은 언제 있었나요?","options":[{"t":"오늘 아침","correct":true},{"t":"어제 저녁","mis":"K1-2-u7-X06"},{"t":"내일 아침","mis":"K1-2-u7-X08"}],"explanation":["첫째 줄에 있어요.","내일은 아직이에요.","언제 칸."],"asset":{"type":"passage","lines":["오늘 아침, 부엌에서 처음으로 달걀을 깨 보았어요.","달걀을 손에 드니 두근두근 설렜어요.","톡 쳤는데 껍데기 조각이 그릇에 빠져서 속상했어요.","숟가락으로 살살 건져 내니 엄마가 손뼉을 쳐 주셨어요.","내 손으로 한 첫 요리라서 뿌듯했어요."],"title":"건우가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#6','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C6',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u7-X12']::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"속상했다","correct":true},{"t":"달걀을 깼다","mis":"K1-2-u7-X12"},{"t":"그릇에 담았다","mis":"K1-2-u7-X12"}],"explanation":["「속상했다」는 마음이 느낀 것이에요.","깨기, 담기는 몸이 한 일이에요.","몸? 마음?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#7','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C7',1,'mc','auto','그 자리에 있었던 것처럼 그려지는 문장은 어느 것인가요?',ARRAY['K1-2-u7-X15']::text[],false,'{"seq":7,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"그 자리에 있었던 것처럼 그려지는 문장은 어느 것인가요?","options":[{"t":"촛불을 후 불자 모두가 손뼉을 치며 노래를 불렀다.","correct":true},{"t":"생일잔치를 했다.","mis":"K1-2-u7-X15"},{"t":"별일 없었다.","mis":"K1-2-u7-X15"}],"explanation":["한 일과 들은 것이 그려져요.","「했다·별일 없었다」는 장면이 흐려요.","본 것·한 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#8','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C8',1,'mc','auto','지율이가 재윤이를 칭찬하는 까닭은 무엇인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":8,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"지율이가 재윤이를 칭찬하는 까닭은 무엇인가요?","options":[{"t":"새 수저를 받아다 주어서","correct":true},{"t":"밥을 가장 빨리 먹어서","mis":"K1-2-u7-X19"},{"t":"수저가 예뻐서","mis":"K1-2-u7-X19"}],"explanation":["재윤이가 한 일이에요.","빨리 먹기, 예쁜 수저는 글에 없어요.","한 일."],"asset":{"type":"passage","lines":["지난 금요일 급식 시간에 내가 수저를 바닥에 떨어뜨렸다.","재윤이가 새 수저를 받아다 주었다.","밥이 식기 전에 먹을 수 있어서 마음이 놓였다."],"title":"지율이가 쓴 칭찬하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#9','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C2',2,'mc','auto','줄마다 되풀이 나오는 낱말은 어느 것인가요?',ARRAY['K1-2-u7-X05']::text[],false,'{"seq":9,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"줄마다 되풀이 나오는 낱말은 어느 것인가요?","options":[{"t":"돋보기","correct":true},{"t":"글씨","mis":"K1-2-u7-X05"},{"t":"잎맥","mis":"K1-2-u7-X05"}],"explanation":["네 줄 모두 「돋보기」.","글씨·잎맥은 한 줄.","동그라미를 쳐 봐요."],"asset":{"type":"passage","lines":["돋보기는 작은 것을 크게 보여 주는 도구입니다.","돋보기로 보면 개미 다리에 난 털도 보입니다.","할머니는 돋보기를 쓰고 작은 글씨를 읽으십니다.","과학 시간에는 돋보기로 나뭇잎의 잎맥을 관찰합니다."],"title":"「돋보기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#10','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C3',2,'match','auto','씨앗과 멀리 퍼지는 방법을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C3","difficulty":2,"kind":"match","stem":"씨앗과 멀리 퍼지는 방법을 선으로 이어 보세요.","pairs":[{"l":"단풍나무 씨앗","r":"날개로 바람을 타요"},{"l":"봉숭아 씨앗","r":"꼬투리가 터져 튀어요"},{"l":"야자 열매","r":"물에 떠서 가요"}],"mis":"K1-2-u7-X06","explanation":["씨앗마다 방법이 달라요.","합치면 씨앗이 퍼지는 방법.","문단을 짚어요."],"asset":{"type":"passage","lines":["단풍나무 씨앗은 날개가 있어 바람을 타고 빙글빙글 날아갑니다.","봉숭아 씨앗은 꼬투리가 톡 터지면서 멀리 튀어 나갑니다.","야자 열매는 물에 둥둥 떠서 먼 바닷가까지 갑니다."],"title":"「멀리멀리 떠나요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#11','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C6',2,'match','auto','장면과 그때 건우의 마음을 선으로 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K1-2-u7-C6","difficulty":2,"kind":"match","stem":"장면과 그때 건우의 마음을 선으로 이어 보세요.","pairs":[{"l":"달걀을 처음 손에 들었을 때","r":"설렜어요"},{"l":"껍데기가 그릇에 빠졌을 때","r":"속상했어요"},{"l":"첫 요리를 마쳤을 때","r":"뿌듯했어요"}],"mis":"K1-2-u7-X13","explanation":["장면이 바뀌면 마음도 바뀌어요.","설렘 → 속상 → 뿌듯.","줄을 짚어요."],"asset":{"type":"passage","lines":["오늘 아침, 부엌에서 처음으로 달걀을 깨 보았어요.","달걀을 손에 드니 두근두근 설렜어요.","톡 쳤는데 껍데기 조각이 그릇에 빠져서 속상했어요.","숟가락으로 살살 건져 내니 엄마가 손뼉을 쳐 주셨어요.","내 손으로 한 첫 요리라서 뿌듯했어요."],"title":"건우가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#12','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C1',2,'ox','auto','설명하는 글은 대충 읽어도 무엇을 해야 할지 다 알 수 있어요.',ARRAY['K1-2-u7-X02']::text[],false,'{"seq":12,"concept":"K1-2-u7-C1","difficulty":2,"kind":"ox","stem":"설명하는 글은 대충 읽어도 무엇을 해야 할지 다 알 수 있어요.","answer":"X","reason_options":[{"t":"차례나 방법을 놓치면 헤매게 되니까","correct":true},{"t":"제목만 읽어도 다 알 수 있으니까","mis":"K1-2-u7-X02"}],"mis":"K1-2-u7-X02","explanation":["꼼꼼히, 차례대로.","한 줄만 놓쳐도 막혀요.","줄마다 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#13','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C5',2,'ox','auto','다음 주에 갈 소풍은 겪은 일로 쓸 수 있어요.',ARRAY['K1-2-u7-X08']::text[],false,'{"seq":13,"concept":"K1-2-u7-C5","difficulty":2,"kind":"ox","stem":"다음 주에 갈 소풍은 겪은 일로 쓸 수 있어요.","answer":"X","reason_options":[{"t":"아직 있지 않은 일이니까","correct":true},{"t":"즐거운 일은 모두 겪은 일이니까","mis":"K1-2-u7-X08"}],"mis":"K1-2-u7-X08","explanation":["겪은 일은 이미 있었던 일이에요.","소풍은 아직 오지 않았어요.","「어제·오늘·지난번」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#14','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C8',2,'mc','auto','칭찬하는 글로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":14,"concept":"K1-2-u7-C8","difficulty":2,"kind":"mc","stem":"칭찬하는 글로 알맞은 것은 어느 것인가요?","options":[{"t":"내 그림에 색칠을 도와주어서 끝까지 완성할 수 있었어.","correct":true},{"t":"네 그림은 내 그림보다 별로야.","mis":"K1-2-u7-X19"},{"t":"너 옷이 예쁘다.","mis":"K1-2-u7-X19"}],"explanation":["한 일과 마음이 있어요.","견주기, 겉모습은 칭찬거리가 아니에요.","한 일 + 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#15','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C7',2,'mc','auto','친구 글을 나누어 읽을 때 살펴볼 것은 어느 것인가요?',ARRAY['K1-2-u7-X18']::text[],false,'{"seq":15,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"친구 글을 나누어 읽을 때 살펴볼 것은 어느 것인가요?","options":[{"t":"어떤 일이 있었는지 장면이 그려지는지","correct":true},{"t":"틀린 글자가 몇 개인지","mis":"K1-2-u7-X18"},{"t":"누가 더 빨리 썼는지","mis":"K1-2-u7-X18"}],"explanation":["장면이 그려지는지 봐요.","틀린 글자·빠르기가 목적이 아니에요.","일과 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#16','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C6',2,'mc','auto','이 표정에 어울리지 않는 말은 어느 것인가요?',ARRAY['K1-2-u7-X13']::text[],false,'{"seq":16,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"이 표정에 어울리지 않는 말은 어느 것인가요?","options":[{"t":"신나다","correct":true},{"t":"서운하다","mis":"K1-2-u7-X13"},{"t":"속상하다","mis":"K1-2-u7-X13"}],"explanation":["눈물이 맺힌 얼굴에 「신나다」는 어울리지 않아요.","서운하다·속상하다는 어울려요.","하나만 다른 것."],"asset":{"type":"scene","icon":"😢","text":"눈물이 맺힌 얼굴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
