INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#18','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C4',3,'error','auto','「멀리멀리 떠나요」를 읽고 새롭게 안 점을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#19','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C5',3,'error','auto','건우가 겪은 일을 네 칸으로 정리했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#20','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C7',3,'mc','auto','소미의 글을 겪은 일이 잘 드러나게 고치려면 무엇을 더하면 좋을까요?',ARRAY['K1-2-u7-X14','K1-2-u7-X11']::text[],false,'{"seq":20,"concept":"K1-2-u7-C7","difficulty":3,"kind":"mc","stem":"소미의 글을 겪은 일이 잘 드러나게 고치려면 무엇을 더하면 좋을까요?","options":[{"t":"고구마를 캘 때 본 것과 한 일을 자세히","correct":true},{"t":"다른 날 한 일을 더 늘어놓기","mis":"K1-2-u7-X14"},{"t":"「재미있었다」를 여러 번 쓰기","mis":"K1-2-u7-X11"}],"explanation":["본 것·한 일을 더해요.","늘어놓기·되풀이는 그대로예요.","그때 무엇이 보였나요?"],"asset":{"type":"passage","lines":["토요일에 텃밭에 갔다.","고구마를 캤다.","재미있었다."],"title":"소미가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#21','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C8',3,'error','auto','칭찬하고 싶은 사람을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#22','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C2',3,'mc','auto','이 글에 「할머니」가 나온 까닭은 무엇인가요?',ARRAY['K1-2-u7-X04','K1-2-u7-X03']::text[],false,'{"seq":22,"concept":"K1-2-u7-C2","difficulty":3,"kind":"mc","stem":"이 글에 「할머니」가 나온 까닭은 무엇인가요?","options":[{"t":"돋보기를 쓰는 때를 보여 주려고","correct":true},{"t":"할머니를 설명하려고","mis":"K1-2-u7-X04"},{"t":"할머니가 제목이라서","mis":"K1-2-u7-X03"}],"explanation":["작은 글씨를 읽을 때 쓴다는 것을 알려 줘요.","할머니는 한 줄뿐이고 제목도 아니에요.","글 전체는 돋보기."],"asset":{"type":"passage","lines":["돋보기는 작은 것을 크게 보여 주는 도구입니다.","돋보기로 보면 개미 다리에 난 털도 보입니다.","할머니는 돋보기를 쓰고 작은 글씨를 읽으십니다.","과학 시간에는 돋보기로 나뭇잎의 잎맥을 관찰합니다."],"title":"「돋보기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#23','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C2',4,'sa','auto','제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇을 설명하는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u7-C2","difficulty":4,"kind":"sa","stem":"제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇을 설명하는지 쓰세요.","answer":["선인장"],"explanation":["세 줄 모두 「선인장」.","가시는 한 줄에만 나와요.","되풀이 낱말."],"asset":{"type":"passage","lines":["선인장은 물이 적은 곳에서도 잘 자랍니다.","선인장은 두꺼운 줄기에 물을 모아 둡니다.","선인장의 가시는 잎이 변한 것입니다."],"title":"제목을 가린 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#24','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C7',4,'essay','teacher','실수했다가 다시 해낸 일을 하나 골라, 한 일·그때 마음이 들어가게 일이 일어난 차례로 세 문장 넘게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u7-C7","difficulty":4,"kind":"essay","stem":"실수했다가 다시 해낸 일을 하나 골라, 한 일·그때 마음이 들어가게 일이 일어난 차례로 세 문장 넘게 쓰세요.","answer_guide":{"answer":"예: 오늘 받아쓰기에서 「깎다」를 「깍다」로 썼다. 쉬는 시간에 공책에 다섯 번 다시 써 보았다. 다음 문제에서 맞게 쓰니 마음이 가벼워졌다. — 한 가지 일이 차례대로, 장면과 까닭 있는 마음이 있으면 맞아요.","scoring_points":["한 가지 일을 골라 자세히 썼는가","한 일로 장면이 그려지는가","마음에 까닭이 있는가"]},"explanation":["하나를 자세히.","차례대로.","마음은 까닭과 함께."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#25','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C8',4,'essay','teacher','이웃 가운데 한 사람(경비원, 가게 주인, 옆집 어른 등)을 골라, 세 칸(언제·칭찬하고 싶은 일·그때 마음)으로 칭찬하는 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u7-C8","difficulty":4,"kind":"essay","stem":"이웃 가운데 한 사람(경비원, 가게 주인, 옆집 어른 등)을 골라, 세 칸(언제·칭찬하고 싶은 일·그때 마음)으로 칭찬하는 글을 쓰세요.","answer_guide":{"answer":"예: 지난주 비 오는 날 경비원 아저씨가 현관 앞에 미끄럼 방지 판을 깔아 주셨다. 넘어지지 않고 집에 들어갈 수 있어서 마음이 놓였다. — 언제·한 일·마음이 있고 견주지 않았으면 맞아요.","scoring_points":["언제가 있는가","그 사람이 한 일이 있는가","그때 마음이 있고 견주거나 점수를 매기지 않았는가"]},"explanation":["세 칸.","한 일을 꼭.","견주지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#1','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C1',1,'mc','auto','이 쪽지는 무엇을 알려 주나요?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":1,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"이 쪽지는 무엇을 알려 주나요?","options":[{"t":"물감을 쓴 붓을 씻는 방법","correct":true},{"t":"그림을 잘 그리는 친구","mis":"K1-2-u7-X01"},{"t":"붓을 산 가게","mis":"K1-2-u7-X01"}],"explanation":["읽으면 붓 씻는 법을 알게 돼요.","친구나 가게 이야기는 없어요.","읽고 나서 무엇을 할 수 있나요?"],"asset":{"type":"passage","lines":["물감을 다 쓰면 붓을 물통에 넣어 살살 흔듭니다.","붓을 휴지에 대고 물기를 닦습니다.","붓 끝을 손가락으로 모아 가지런히 합니다.","붓을 눕혀서 말립니다."],"title":"「붓을 씻는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#2','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C2',1,'mc','auto','이 글은 무엇을 설명하나요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":2,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"이 글은 무엇을 설명하나요?","options":[{"t":"소금","correct":true},{"t":"바닷물","mis":"K1-2-u7-X04"},{"t":"배추","mis":"K1-2-u7-X04"}],"explanation":["모든 줄에 소금이 나와요.","바닷물·배추는 한 줄에만 나와요.","모든 줄에 나오는 것."],"asset":{"type":"passage","lines":["소금은 짠맛이 나는 하얀 알갱이입니다.","소금은 바닷물을 햇볕에 말려서 얻습니다.","음식에 소금을 조금 넣으면 맛이 살아납니다.","배추를 소금에 절이면 오래 두고 먹을 수 있습니다."],"title":"「소금」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#3','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C3',1,'mc','auto','이 글 전체가 설명하는 것은 무엇인가요?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"이 글 전체가 설명하는 것은 무엇인가요?","options":[{"t":"소리로 알려 주는 물건들","correct":true},{"t":"땡 소리","mis":"K1-2-u7-X03"},{"t":"구급차","mis":"K1-2-u7-X04"}],"explanation":["세 문단을 합치면 소리로 알려 주는 물건들이에요.","땡은 제목의 소리, 구급차는 한 문단이에요.","문단을 합쳐요."],"asset":{"type":"passage","lines":["초인종은 띵동 소리로 손님이 왔다고 알립니다.","구급차는 삐뽀삐뽀 소리로 길을 비켜 달라고 알립니다.","전자레인지는 땡 소리로 음식이 다 데워졌다고 알립니다."],"title":"「띵동, 삐뽀, 땡!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#4','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C4',1,'mc','auto','글을 읽고 새롭게 안 점으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X07']::text[],false,'{"seq":4,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 새롭게 안 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"소금은 바닷물을 햇볕에 말려서 얻는다는 것","correct":true},{"t":"소금은 단맛이 난다는 것","mis":"K1-2-u7-X07"},{"t":"소금은 나무에서 딴다는 것","mis":"K1-2-u7-X07"}],"explanation":["둘째 줄에 있어요.","단맛, 나무 이야기는 없어요.","글 어디에 있나요?"],"asset":{"type":"passage","lines":["소금은 짠맛이 나는 하얀 알갱이입니다.","소금은 바닷물을 햇볕에 말려서 얻습니다.","음식에 소금을 조금 넣으면 맛이 살아납니다.","배추를 소금에 절이면 오래 두고 먹을 수 있습니다."],"title":"「소금」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#5','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C5',1,'mc','auto','아린이에게 있었던 일은 어디에서 있었나요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":5,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"아린이에게 있었던 일은 어디에서 있었나요?","options":[{"t":"급식실","correct":true},{"t":"보건실","mis":"K1-2-u7-X06"},{"t":"운동장","mis":"K1-2-u7-X06"}],"explanation":["첫째 줄에 있어요.","보건실·운동장은 글에 없어요.","어디에서 칸."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 사과를 먹었어요.","사각 깨무는데 흔들리던 앞니가 쏙 빠졌어요.","피가 조금 나서 덜컥 겁이 났어요.","선생님이 휴지를 주시며 괜찮다고 하셔서 마음이 놓였어요.","빠진 이를 작은 통에 담아 오니 신기하고 자랑스러웠어요."],"title":"아린이가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#6','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C6',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u7-X12']::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"자랑스러웠다","correct":true},{"t":"사과를 깨물었다","mis":"K1-2-u7-X12"},{"t":"통에 담아 왔다","mis":"K1-2-u7-X12"}],"explanation":["「자랑스러웠다」는 마음이 느낀 것이에요.","깨물기, 담아 오기는 몸이 한 일이에요.","몸? 마음?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#7','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C7',1,'mc','auto','그 자리에 있었던 것처럼 그려지는 문장은 어느 것인가요?',ARRAY['K1-2-u7-X15']::text[],false,'{"seq":7,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"그 자리에 있었던 것처럼 그려지는 문장은 어느 것인가요?","options":[{"t":"낙엽을 밟을 때마다 바스락바스락 소리가 났다.","correct":true},{"t":"공원을 걸었다.","mis":"K1-2-u7-X15"},{"t":"그냥 놀았다.","mis":"K1-2-u7-X15"}],"explanation":["들은 소리가 그려져요.","「걸었다·그냥 놀았다」는 장면이 흐려요.","본 것·들은 것."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#8','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C8',1,'mc','auto','건우가 할아버지를 칭찬하는 까닭은 무엇인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":8,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"건우가 할아버지를 칭찬하는 까닭은 무엇인가요?","options":[{"t":"운동화 끈을 단단히 매어 주셔서","correct":true},{"t":"달리기를 잘하셔서","mis":"K1-2-u7-X19"},{"t":"운동화를 사 주셔서","mis":"K1-2-u7-X19"}],"explanation":["할아버지가 해 주신 일이에요.","달리기, 운동화 사기는 글에 없어요.","한 일."],"asset":{"type":"passage","lines":["어제 저녁 할아버지께서 내 운동화 끈을 단단히 매어 주셨다.","오늘 달리기에서 끈이 한 번도 풀리지 않았다.","할아버지 손이 함께 달려 주는 것 같아 든든했다."],"title":"건우가 쓴 칭찬하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#9','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C2',2,'mc','auto','줄마다 되풀이 나오는 낱말은 어느 것인가요?',ARRAY['K1-2-u7-X05']::text[],false,'{"seq":9,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"줄마다 되풀이 나오는 낱말은 어느 것인가요?","options":[{"t":"소금","correct":true},{"t":"음식","mis":"K1-2-u7-X05"},{"t":"햇볕","mis":"K1-2-u7-X05"}],"explanation":["네 줄 모두 「소금」.","음식·햇볕은 한 줄.","동그라미를 쳐 봐요."],"asset":{"type":"passage","lines":["소금은 짠맛이 나는 하얀 알갱이입니다.","소금은 바닷물을 햇볕에 말려서 얻습니다.","음식에 소금을 조금 넣으면 맛이 살아납니다.","배추를 소금에 절이면 오래 두고 먹을 수 있습니다."],"title":"「소금」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#10','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C3',2,'match','auto','물건과 그 소리가 알려 주는 것을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C3","difficulty":2,"kind":"match","stem":"물건과 그 소리가 알려 주는 것을 선으로 이어 보세요.","pairs":[{"l":"초인종","r":"손님이 왔어요"},{"l":"구급차","r":"길을 비켜 주세요"},{"l":"전자레인지","r":"음식이 다 데워졌어요"}],"mis":"K1-2-u7-X06","explanation":["물건마다 알리는 것이 달라요.","합치면 소리로 알려 주는 물건들.","문단을 짚어요."],"asset":{"type":"passage","lines":["초인종은 띵동 소리로 손님이 왔다고 알립니다.","구급차는 삐뽀삐뽀 소리로 길을 비켜 달라고 알립니다.","전자레인지는 땡 소리로 음식이 다 데워졌다고 알립니다."],"title":"「띵동, 삐뽀, 땡!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#11','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C6',2,'match','auto','장면과 그때 아린이의 마음을 선으로 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K1-2-u7-C6","difficulty":2,"kind":"match","stem":"장면과 그때 아린이의 마음을 선으로 이어 보세요.","pairs":[{"l":"이가 빠져 피가 났을 때","r":"덜컥 겁이 났어요"},{"l":"선생님이 괜찮다고 하셨을 때","r":"마음이 놓였어요"},{"l":"빠진 이를 담아 왔을 때","r":"신기하고 자랑스러웠어요"}],"mis":"K1-2-u7-X13","explanation":["장면이 바뀌면 마음도 바뀌어요.","겁 → 놓임 → 자랑.","줄을 짚어요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 사과를 먹었어요.","사각 깨무는데 흔들리던 앞니가 쏙 빠졌어요.","피가 조금 나서 덜컥 겁이 났어요.","선생님이 휴지를 주시며 괜찮다고 하셔서 마음이 놓였어요.","빠진 이를 작은 통에 담아 오니 신기하고 자랑스러웠어요."],"title":"아린이가 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#12','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C1',2,'ox','auto','「어제 바닷가에 간 일」은 설명하는 글이에요.',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":12,"concept":"K1-2-u7-C1","difficulty":2,"kind":"ox","stem":"「어제 바닷가에 간 일」은 설명하는 글이에요.","answer":"X","reason_options":[{"t":"겪은 일을 쓴 글이지 방법을 알려 주는 글이 아니니까","correct":true},{"t":"바닷가는 설명할 수 없는 곳이니까","mis":"K1-2-u7-X01"}],"mis":"K1-2-u7-X01","explanation":["겪은 일을 쓴 글이에요.","설명하는 글은 무엇인지·어떻게 하는지를 알려 줘요.","읽고 무엇을 알게 되나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#13','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C5',2,'ox','auto','급식을 먹다 이가 빠진 일처럼 학교에서 있었던 일도 글감이 돼요.',ARRAY['K1-2-u7-X09']::text[],false,'{"seq":13,"concept":"K1-2-u7-C5","difficulty":2,"kind":"ox","stem":"급식을 먹다 이가 빠진 일처럼 학교에서 있었던 일도 글감이 돼요.","answer":"O","reason_options":[{"t":"날마다 있는 곳에서도 마음이 움직인 일이 생기니까","correct":true},{"t":"학교에서 있었던 일은 모두 같으니까","mis":"K1-2-u7-X09"}],"mis":"K1-2-u7-X09","explanation":["학교 일도 좋은 글감이에요.","특별하지 않아도 돼요.","마음이 움직인 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#14','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C8',2,'mc','auto','칭찬하는 글로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":14,"concept":"K1-2-u7-C8","difficulty":2,"kind":"mc","stem":"칭찬하는 글로 알맞은 것은 어느 것인가요?","options":[{"t":"쉬는 시간에 혼자 있던 나에게 같이 놀자고 해 주어서 반가웠어.","correct":true},{"t":"너는 나보다 공부를 못하지만 괜찮아.","mis":"K1-2-u7-X19"},{"t":"넌 착한 편이야.","mis":"K1-2-u7-X19"}],"explanation":["한 일과 마음이 있어요.","견주기, 뭉뚱그린 말은 칭찬이 잘 안 전해져요.","한 일 + 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#15','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C7',2,'mc','auto','친구 글을 나누어 읽고 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X18']::text[],false,'{"seq":15,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"친구 글을 나누어 읽고 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「바스락바스락」이라는 말 덕분에 소리가 들리는 것 같아.","correct":true},{"t":"글자가 두 개 틀렸네.","mis":"K1-2-u7-X18"},{"t":"내 글이 더 길어.","mis":"K1-2-u7-X18"}],"explanation":["좋은 표현을 짚어 칭찬했어요.","틀린 글자만, 길이 견주기는 도움이 안 돼요.","좋은 점부터."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#16','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C6',2,'mc','auto','이 표정에 어울리지 않는 말은 어느 것인가요?',ARRAY['K1-2-u7-X13']::text[],false,'{"seq":16,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"이 표정에 어울리지 않는 말은 어느 것인가요?","options":[{"t":"설레다","correct":true},{"t":"짜증 나다","mis":"K1-2-u7-X13"},{"t":"억울하다","mis":"K1-2-u7-X13"}],"explanation":["찌푸린 얼굴에 「설레다」는 어울리지 않아요.","짜증 나다·억울하다는 어울려요.","하나만 다른 것."],"asset":{"type":"scene","icon":"😠","text":"눈썹을 찌푸린 얼굴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#17','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C3',3,'error','auto','「띵동, 삐뽀, 땡!」이 무엇을 설명하는지 친구들이 답했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#18','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C4',3,'error','auto','「띵동, 삐뽀, 땡!」을 읽고 새롭게 안 점을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#19','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C5',3,'error','auto','아린이가 겪은 일을 네 칸으로 정리했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#20','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C7',3,'mc','auto','글감을 고르는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u7-X14','K1-2-u7-X16']::text[],false,'{"seq":20,"concept":"K1-2-u7-C7","difficulty":3,"kind":"mc","stem":"글감을 고르는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지금도 생각나고 누군가에게 들려주고 싶은 일을 골라요","correct":true},{"t":"하루에 한 일을 모두 골라요","mis":"K1-2-u7-X14"},{"t":"친구가 겪은 재미있는 일을 골라요","mis":"K1-2-u7-X16"}],"explanation":["들려주고 싶은 말이 있는 일.","다 고르거나 남의 일은 알맞지 않아요.","누구에게 들려줄까?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#21','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C8',3,'error','auto','칭찬하는 글에 넣을 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#22','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C2',3,'mc','auto','이 글에 「배추」가 나온 까닭은 무엇인가요?',ARRAY['K1-2-u7-X04','K1-2-u7-X03']::text[],false,'{"seq":22,"concept":"K1-2-u7-C2","difficulty":3,"kind":"mc","stem":"이 글에 「배추」가 나온 까닭은 무엇인가요?","options":[{"t":"소금이 하는 일을 보여 주려고","correct":true},{"t":"배추를 설명하려고","mis":"K1-2-u7-X04"},{"t":"배추가 제목이라서","mis":"K1-2-u7-X03"}],"explanation":["소금에 절이면 오래 둔다는 것을 알려 줘요.","배추는 한 줄뿐이고 제목도 아니에요.","글 전체는 소금."],"asset":{"type":"passage","lines":["소금은 짠맛이 나는 하얀 알갱이입니다.","소금은 바닷물을 햇볕에 말려서 얻습니다.","음식에 소금을 조금 넣으면 맛이 살아납니다.","배추를 소금에 절이면 오래 두고 먹을 수 있습니다."],"title":"「소금」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#23','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C2',4,'sa','auto','제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇을 설명하는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u7-C2","difficulty":4,"kind":"sa","stem":"제목을 가린 글이에요. 줄마다 되풀이 나오는 낱말을 찾아, 이 글이 무엇을 설명하는지 쓰세요.","answer":["고드름"],"explanation":["네 줄 모두 「고드름」.","처마·눈은 실마리일 뿐이에요.","되풀이 낱말."],"asset":{"type":"passage","lines":["겨울 아침 처마 끝에 고드름이 매달립니다.","고드름은 녹은 눈이 떨어지다 다시 얼어서 생깁니다.","고드름은 해가 나면 똑똑 녹아 떨어집니다.","고드름 밑으로 지나갈 때는 조심해야 합니다."],"title":"제목을 가린 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#24','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C7',4,'essay','teacher','깜짝 놀랐던 일을 하나 골라, 본 것·한 일·그때 마음이 들어가게 일이 일어난 차례로 세 문장 넘게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u7-C7","difficulty":4,"kind":"essay","stem":"깜짝 놀랐던 일을 하나 골라, 본 것·한 일·그때 마음이 들어가게 일이 일어난 차례로 세 문장 넘게 쓰세요.","answer_guide":{"answer":"예: 지난주 학교 화단에서 잎을 뒤집어 보았다. 잎 뒤에 초록 애벌레가 꼼지락거리고 있었다. 손을 얼른 뺐지만 자꾸 들여다보고 싶을 만큼 신기했다. — 한 가지 일이 차례대로, 장면과 까닭 있는 마음이 있으면 맞아요.","scoring_points":["한 가지 일을 골라 자세히 썼는가","본 것이나 한 일로 장면이 그려지는가","마음에 까닭이 있는가"]},"explanation":["하나를 자세히.","차례대로.","마음은 까닭과 함께."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#25','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C8',4,'essay','teacher','같은 반 친구 한 명을 골라, 세 칸(언제·칭찬하고 싶은 일·그때 마음)으로 칭찬하는 글을 쓰세요. 「착해·최고야」 같은 말 대신 겪은 일을 넣으세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u7-C8","difficulty":4,"kind":"essay","stem":"같은 반 친구 한 명을 골라, 세 칸(언제·칭찬하고 싶은 일·그때 마음)으로 칭찬하는 글을 쓰세요. 「착해·최고야」 같은 말 대신 겪은 일을 넣으세요.","answer_guide":{"answer":"예: 오늘 쉬는 시간에 짝이 내 필통을 같이 찾아 주었다. 책상 밑에서 찾았을 때 고맙고 반가웠다. — 언제·한 일·마음이 있고 뭉뚱그리지 않았으면 맞아요.","scoring_points":["언제가 있는가","친구가 한 일이 있는가","그때 마음이 있고 「착해·최고야」로 그치지 않았는가"]},"explanation":["세 칸.","한 일을 꼭.","뭉뚱그리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
